  function _isStaging() {
    try {
      if (typeof window !== 'undefined' && window.IS_STAGING_ENV === true) return true;
      const path = (typeof window !== 'undefined' && window.location && window.location.pathname) || '';
      if (path.includes('stage-x91-k8q7') || path.includes('test-sandbox')) return true;
      if (typeof window !== 'undefined' && window.location && window.location.search && window.location.search.includes('staging=1')) return true;
    } catch (e) {}
    return false;
  }

  async function getMaintenanceStatus() {
    if (_isStaging()) {
      return { active: false, enabled: false, message: '' };
    }
    try {
      // Direct fetch with guaranteed no-cache to bypass all HTTP caching layers
      const res = await fetch(
        `${SUPABASE_URL}/rest/v1/globals?id=eq.maintenance`,
        {
          method: 'GET',
          cache: 'no-store',
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${SUPABASE_ANON_KEY}`,
            'Content-Type': 'application/json',
            'Cache-Control': 'no-cache, no-store, must-revalidate',
            'Pragma': 'no-cache',
            'Expires': '0'
          }
        }
      );
      if (!res.ok) return { active: false, message: '' };
      const rows = await res.json();
      if (rows && rows.length > 0 && rows[0].data) {
        return rows[0].data;
      }
    } catch (e) {}
    return { active: false, message: '' };
  }

