  async function submitTopupRequest(requestData) {
    const ts = Date.now();

    // 1. Authoritative ServerBridge: routes via backend service_role key (bypasses RLS entirely)
    if (typeof ServerBridge !== 'undefined' && typeof ServerBridge.submitTopupRequest === 'function' && ServerBridge.isServerOnline()) {
      try {
        const bridgeReq = await ServerBridge.submitTopupRequest(requestData);
        if (bridgeReq) {
          console.log('[DB] Topup request submitted via Authoritative ServerBridge:', bridgeReq.id);
          return bridgeReq;
        }
      } catch (bridgeErr) {
        console.warn('[DB] ServerBridge submitTopupRequest fallback:', bridgeErr.message);
      }
    }

    const newRequest = {
      id:'req_' + ts +'_' + Math.random().toString(36).substring(2, 7),
      username: (requestData.username ||'').trim(),
      packageId: requestData.packageId,
      packageName: requestData.packageName,
      price: Number(requestData.price) || 0,
      rewards: requestData.rewards || {},
      senderPhoneOrName: (requestData.senderPhoneOrName ||'').trim(),
      receiptNumber: (requestData.receiptNumber ||'').trim(),
      status:'pending',
      createdAt: ts,
      reviewedAt: null,
      reviewerNote:''
    };

    // 2. PostgreSQL Atomic RPC Function (SECURITY DEFINER, race-condition free)
    try {
      const rpcRes = await _api('rpc/submit_topup_request', {
        method: 'POST',
        body: JSON.stringify({ request_data: newRequest })
      });
      if (rpcRes) {
        console.log('[DB] Topup request submitted via Supabase RPC:', newRequest.id);
        return newRequest;
      }
    } catch (rpcErr) {
      // If RPC is not present yet or fails, proceed to direct globals write
    }

    // 3. Direct globals write (allowed by updated RLS policy)
    let currentRequests = [];
    try {
      const rows = await _api(`globals?id=eq.topup_requests`);
      if (rows && rows.length > 0 && rows[0].data && Array.isArray(rows[0].data.requests)) {
        currentRequests = rows[0].data.requests;
      }
    } catch (e) {}

    currentRequests.unshift(newRequest);
    if (currentRequests.length > 300) {
      currentRequests = currentRequests.slice(0, 300);
    }

    await _api('globals', {
      method:'POST',
      headers: {'Prefer':'resolution=merge-duplicates' },
      body: JSON.stringify({
        id:'topup_requests',
        data: { requests: currentRequests, updatedAt: ts },
        updated_at: ts
      })
    });

    return newRequest;
  }

  async function getTopupRequests() {
    try {
      const rows = await _api(`globals?id=eq.topup_requests`);
      if (rows && rows.length > 0 && rows[0].data && Array.isArray(rows[0].data.requests)) {
        return rows[0].data.requests;
      }
    } catch (e) {}
    return [];
  }

  async function getPlayerData(username) {
    if (!username) return null;
    const cleanUser = String(username).replace(/^@/, '').trim();
    try {
      const rows = await _api(`players?username=eq.${encodeURIComponent(cleanUser)}&select=*`);
      return (rows && rows.length > 0) ? rows[0] : null;
    } catch (e) {
      return null;
    }
  }

  async function processTopupRequest(requestId, action, reviewerNote ='') {
    const ts = Date.now();
    const rows = await _api(`globals?id=eq.topup_requests`);
    if (!rows || rows.length === 0 || !rows[0].data || !Array.isArray(rows[0].data.requests)) {
      throw new Error('لم يتم العثور على سجل طلبات الشحن.');
    }

    const requests = rows[0].data.requests;
    const reqIndex = requests.findIndex(r => r.id === requestId);
    if (reqIndex === -1) {
      throw new Error('طلب الشحن غير موجود.');
    }

    const req = requests[reqIndex];
    if (req.status !=='pending') {
      throw new Error(`تمت معالجة هذا الطلب مسبقاً (${req.status ==='approved' ?'مقبول' :'مرفوض'}).`);
    }

    if (action ==='approved') {
      const targetUser = req.username;
      const playerDoc = await getPlayerData(targetUser);
      if (!playerDoc) {
        throw new Error(`حساب اللاعب"${targetUser}" غير موجود بقاعدة البيانات.`);
      }

      const pState = playerDoc.state || {};
      const rewards = req.rewards || {};
      const pkgDef = (typeof DEFAULT_TOPUP_PACKAGES !== 'undefined' && Array.isArray(DEFAULT_TOPUP_PACKAGES)) 
        ? DEFAULT_TOPUP_PACKAGES.find(p => p.id === req.packageId) 
        : null;

      const addedCash = Number(rewards.cash !== undefined ? rewards.cash : (pkgDef ? pkgDef.cash : 0)) || 0;
      const addedBank = Number(rewards.bank !== undefined ? rewards.bank : (pkgDef ? pkgDef.bank : 0)) || 0;
      const addedXP = Number(rewards.xp !== undefined ? rewards.xp : (pkgDef ? pkgDef.xp : 0)) || 0;
      const addedGold = Number(rewards.gold !== undefined ? rewards.gold : (pkgDef ? pkgDef.gold : 0)) || 0;
      const customBadge = rewards.customBadge || (pkgDef ? pkgDef.customBadge : '') || '';

      const updatedCash = (Number(playerDoc.cash) || 0) + addedCash;
      const updatedBank = (Number(playerDoc.bank) || 0) + addedBank;
      const updatedXP = (Number(playerDoc.xp) || 0) + addedXP;
      const updatedGold = (Number(playerDoc.gold) || 0) + addedGold;
      const updatedNetworth = updatedCash + updatedBank;

      pState.cash = updatedCash;
      pState.bank = updatedBank;
      pState.xp = updatedXP;
      pState.gold = updatedGold;
      pState.netWorth = updatedNetworth;

      if (customBadge) {
        pState.customBadge = customBadge;
        pState.badgeTitle = rewards.badgeTitle || req.packageName;
      }

      // VIP package features (Chat Glow, Verification Badge, Titles)
      if (req.packageId === 'pkg_vip_chat_glow') {
        pState.chatGlow = 'gold_neon';
        pState.hasChatGlow = true;
        pState.activePackage = 'pkg_vip_chat_glow';
      } else if (req.packageId === 'pkg_vip_royal_ultimate') {
        pState.chatGlow = 'cyber_rainbow';
        pState.hasChatGlow = true;
        pState.isVerified = true;
        pState.vipVerified = true;
        pState.activePackage = 'pkg_vip_royal_ultimate';
      } else if (req.packageId === 'pkg_vip_crimson_flame') {
        pState.chatGlow = 'crimson_flame';
        pState.hasChatGlow = true;
        pState.activePackage = 'pkg_vip_crimson_flame';
      } else if (req.packageId === 'pkg_vip_svip_blue_flame') {
        pState.chatGlow = 'blue_flame';
        pState.hasChatGlow = true;
        pState.customBadge = 'SVIP';
        pState.badgeTitle = 'SVIP';
        pState.activePackage = 'pkg_vip_svip_blue_flame';
      } else if (req.packageId === 'pkg_vip_verified') {
        pState.isVerified = true;
        pState.vipVerified = true;
        pState.activePackage = 'pkg_vip_verified';
      }

      pState.hasPurchasedTopup = true;
      pState.purchasedTopups = (pState.purchasedTopups || 0) + 1;

      if (rewards.features) {
        if (rewards.features.chatGlow) {
          pState.chatGlow = rewards.features.chatGlow;
          pState.hasChatGlow = true;
        }
        if (rewards.features.verified) { pState.isVerified = true; pState.vipVerified = true; }
        if (rewards.features.title) pState.title = rewards.features.title;
        if (rewards.features.stickersPack) pState.stickersPack = true;
        if (rewards.features.customAvatar) pState.canUploadAvatar = true;
      }

      if (rewards.items && typeof rewards.items ==='object') {
        pState.inventory = pState.inventory || {};
        for (const [itemId, qty] of Object.entries(rewards.items)) {
          pState.inventory[itemId] = (Number(pState.inventory[itemId]) || 0) + Number(qty);
        }
      }

      // Record permanent approved top-up in player activityLog and adminGrants
      const topupEntry = {
        id: `topup_${requestId}`,
        timestamp: ts,
        action: `شحنة معتمدة من الإدارة 👑 (${req.packageName || 'باقة متجر'})`,
        category: 'admin',
        details: `تم اعتماد وشحن باقة "${req.packageName}" بنجاح (${reviewerNote || 'معتمد بواسطة الإدارة'})`,
        amount: addedCash + addedBank,
        gold: addedGold || null,
        cash: updatedCash,
        bank: updatedBank
      };
      if (!Array.isArray(pState.activityLog)) pState.activityLog = [];
      pState.activityLog.unshift(topupEntry);
      if (!Array.isArray(pState.adminGrants)) pState.adminGrants = [];
      pState.adminGrants.unshift({
        id: topupEntry.id,
        type: 'topup',
        packageId: req.packageId,
        packageName: req.packageName,
        price: req.price,
        cash: addedCash + addedBank,
        gold: addedGold || 0,
        status: 'approved',
        note: reviewerNote || '',
        timestamp: ts
      });

      pState.adminModifiedTimestamp = ts;

      await adminSavePlayer(targetUser, {
        cash: updatedCash,
        bank: updatedBank,
        gold: updatedGold,
        xp: updatedXP,
        netWorth: updatedNetworth,
        state: pState,
        adminModifiedTimestamp: ts
      });

      // Automatically backfill any existing messages in chat_feed so they glow immediately
      if (pState.chatGlow) {
        try {
          const feedRows = await _api("globals?id=eq.chat_feed&select=data");
          if (feedRows && feedRows.length > 0 && feedRows[0].data && Array.isArray(feedRows[0].data.messages)) {
            let feedModified = false;
            feedRows[0].data.messages.forEach(m => {
              if (m.sender === targetUser) {
                m.chatGlow = pState.chatGlow;
                if (pState.isVerified) m.isVerified = true;
                if (pState.customBadge) m.customBadge = pState.customBadge;
                feedModified = true;
              }
            });
            if (feedModified) {
              await _api('globals?id=eq.chat_feed', {
                method: 'PATCH',
                body: JSON.stringify({
                  data: { messages: feedRows[0].data.messages },
                  updated_at: Date.now()
                })
              });
            }
          }
        } catch (errFeed) {
          console.warn('[DB] Chat feed backfill warning:', errFeed.message);
        }
      }

      const topupReceiptData = {
        packageId: req.packageId,
        packageName: req.packageName,
        price: req.price,
        cash: addedCash,
        bank: addedBank,
        gold: addedGold,
        xp: addedXP,
        newCash: updatedCash,
        newBank: updatedBank,
        newGold: updatedGold,
        newXp: updatedXP,
        newWorth: updatedNetworth,
        isPreApplied: true,
        customBadge: customBadge,
        badgeTitle: rewards.badgeTitle || req.packageName,
        items: rewards.items || {},
        status:'approved',
        date: ts,
        receiptNumber: req.receiptNumber ||'',
        senderPhoneOrName: req.senderPhoneOrName ||'',
        reviewerNote: req.reviewerNote ||'تم الاعتماد والشحن بنجاح'
      };

      await sendMail('SYSTEM', targetUser,'topup_receipt', {
        title:` تم شحن باقة [${req.packageName}] بنجاح!`,
        message:`تم اعتماد تحويلك بمبلغ ${req.price} ج.م وإيداع جميع مزايا باقتك بحسابك بنجاح.`,
        topupDetails: topupReceiptData
      }).catch(() => {});

      if (addedCash > 0 || addedBank > 0) {
        await sendMail('إدارة اللعبة (Financial Team)', targetUser, 'admin_balance_grant', {
          addedCash: addedCash,
          addedBank: addedBank,
          totalAmount: addedCash + addedBank,
          target: targetUser,
          newCash: updatedCash,
          newBank: updatedBank,
          newXp: updatedXP,
          isPreApplied: true,
          timestamp: ts,
          note: `شحن فوري معتمد: [${req.packageName}]`
        }).catch(() => {});
      }

      if (addedGold > 0) {
        await sendMail('إدارة اللعبة (Financial Team)', targetUser, 'admin_gold_grant', {
          addedGold: addedGold,
          newGold: updatedGold,
          isPreApplied: true,
          timestamp: ts,
          note: `شحن سبائك الذهب: [${req.packageName}]`
        }).catch(() => {});
      }

      req.status ='approved';
      req.reviewedAt = ts;
      req.reviewerNote = reviewerNote ||'تم الاعتماد والشحن بنجاح';
    } else {
      req.status ='rejected';
      req.reviewedAt = ts;
      req.reviewerNote = reviewerNote ||'تم رفض الطلب لعدم تطابق بيانات التحويل';

      const topupRejectData = {
        packageId: req.packageId,
        packageName: req.packageName,
        price: req.price,
        status:'rejected',
        date: ts,
        receiptNumber: req.receiptNumber ||'',
        senderPhoneOrName: req.senderPhoneOrName ||'',
        reviewerNote: req.reviewerNote ||'تم رفض الطلب لعدم تطابق بيانات التحويل'
      };

      await sendMail('SYSTEM', req.username,'topup_receipt', {
        title:`️ تعذر اعتماد طلب شحن [${req.packageName}]`,
        message:`نعتذر، لم تتمكن الإدارة من اعتماد طلب الشحن الخاص بك.\nالسبب: ${req.reviewerNote}\nيرجى التواصل مع الإدارة أو التأكد من بيانات التحويل وإعادة الطلب.`,
        topupDetails: topupRejectData
      }).catch(() => {});
    }

    await _api('globals?id=eq.topup_requests', {
      method:'PATCH',
      body: JSON.stringify({
        data: { requests, updatedAt: ts },
        updated_at: ts
      })
    });

    return req;
  }

  async function deleteTopupRequest(requestId) {
    if (!requestId) throw new Error('معرف الطلب غير صالح.');
    const ts = Date.now();
    const rows = await _api(`globals?id=eq.topup_requests`);
    if (!rows || rows.length === 0 || !rows[0].data || !Array.isArray(rows[0].data.requests)) {
      throw new Error('لم يتم العثور على سجل طلبات الشحن.');
    }

    const requests = rows[0].data.requests;
    const reqIndex = requests.findIndex(r => r.id === requestId);
    if (reqIndex === -1) {
      throw new Error('طلب الشحن غير موجود.');
    }

    requests.splice(reqIndex, 1);

    await _api('globals?id=eq.topup_requests', {
      method:'PATCH',
      body: JSON.stringify({
        data: { requests, updatedAt: ts },
        updated_at: ts
      })
    });

    return true;
  }

  // ─────────────────────────────────────────────
  //  SYSTEM STATS & ADMIN PANEL
  // ─────────────────────────────────────────────
  const HIDDEN_ADMIN_USERNAMES = ['khaled', 'newu', 'rasalmal', 'rasalmal1', 'rasalmal2'];

  async function getSystemStats() {
    try {
      const rows = await _api('players?select=username,cash,bank,dirty_cash,net_worth,xp,is_banned,jail_timer,title,last_seen&limit=10000');
      let totalCash = 0, totalBank = 0, totalNetWorth = 0;
      let jailedCount = 0, bannedCount = 0;
      let billionaires = 0, millionaires = 0, middleClass = 0, workingClass = 0;
      let onlineCount = 0;
      const ONLINE_THRESHOLD = 2.5 * 60 * 1000; // 2.5 minutes (150s)
      const now = Date.now();
      const allPlayersList = [];

      // Filter out Master Admin and internal test accounts completely from dashboard analytics
      const filteredRows = (rows || []).filter(r => {
        const u = String(r.username || '').trim().toLowerCase();
        return !HIDDEN_ADMIN_USERNAMES.includes(u);
      });

      filteredRows.forEach(r => {
        const cash = Number(r.cash || 0);
        const bank = Number(r.bank || 0);
        const nw = Number(r.net_worth || 0);
        const lastSeen = Number(r.last_seen || 0);
        const isOnline = lastSeen > 0 && (now - lastSeen) < ONLINE_THRESHOLD;
        if (isOnline) onlineCount++;

        totalCash += cash;
        totalBank += bank;
        totalNetWorth += nw;

        if (Number(r.jail_timer) > 0) jailedCount++;
        if (r.is_banned) bannedCount++;

        if (nw >= 50000000) billionaires++;
        else if (nw >= 5000000) millionaires++;
        else if (nw >= 500000) middleClass++;
        else workingClass++;

        allPlayersList.push({
          username: r.username,
          cash,
          bank,
          netWorth: nw,
          xp: Number(r.xp || 0),
          title: r.title,
          isBanned: r.is_banned,
          isJailed: Number(r.jail_timer) > 0,
          lastSeen,
          last_seen: lastSeen,
          lastActiveTimestamp: lastSeen,
          isOnline
        });
      });

      allPlayersList.sort((a, b) => b.netWorth - a.netWorth);

      return {
        totalPlayers: filteredRows.length,
        scannedPlayers: filteredRows.length,
        onlineCount,
        isFromCache: false,
        quotaExceeded: false,
        totalCash,
        totalBank,
        totalNetWorth,
        jailedCount,
        bannedCount,
        billionaires,
        millionaires,
        middleClass,
        workingClass,
        wealthBrackets: {
          billionaires,
          millionaires,
          middleClass,
          workingClass
        },
        topRichest: allPlayersList.slice(0, 5),
        allPlayers: allPlayersList,
        suspiciousPlayers: []
      };
    } catch (err) {
      console.warn('[DB] getSystemStats error:', err.message);
      return { totalPlayers: 0, onlineCount: 0, totalCash: 0, totalBank: 0, totalNetWorth: 0, jailedCount: 0, bannedCount: 0, wealthBrackets: { billionaires: 0, millionaires: 0, middleClass: 0, workingClass: 0 } };
    }
  }

  async function adminGetAllPlayers() {
    const rows = await _api('players?select=username,pin,cash,bank,dirty_cash,net_worth,xp,title,job_id,is_admin,is_banned,jail_timer,total_taxes_paid,afk_manager_expires_at,last_seen,created_at,state&order=net_worth.desc&limit=10000');
    return (rows || []).filter(r => !HIDDEN_ADMIN_USERNAMES.includes(String(r.username || '').trim().toLowerCase())).map(r => {
      let stateObj = {};
      if (r.state) {
        if (typeof r.state === 'object') stateObj = r.state;
        else if (typeof r.state === 'string') {
          try { stateObj = JSON.parse(r.state); } catch(e) {}
        }
      }
      const p = { ...stateObj };
      p.state = stateObj;
      p.username = r.username;
      p.pin = r.pin;
      p.cash = Number(r.cash || 0);
      p.bank = Number(r.bank || 0);
      p.dirtyCash = Number(r.dirty_cash || 0);
      p.netWorth = Number(r.net_worth || 0);
      p.xp = Number(r.xp || 0);
      p.title = r.title || 'عامل مبتدئ';
      p.jobId = r.job_id || 'worker';
      p.isAdmin = r.is_admin === true;
      p.isBanned = r.is_banned === true;
      p.jailTimer = Number(r.jail_timer || 0);
      p.totalTaxesPaid = Number(r.total_taxes_paid || 0);
      p.afkManagerExpiresAt = Number(r.afk_manager_expires_at || 0);
      p.lastSeen = Number(r.last_seen || 0);
      p.lastActiveTimestamp = p.lastSeen;
      p.last_seen = p.lastSeen;
      p.createdAt = Number(r.created_at || 0);

      // Keep snake_case mirrors as well
      p.is_admin = p.isAdmin;
      p.is_banned = p.isBanned;
      p.jail_timer = p.jailTimer;
      p.net_worth = p.netWorth;
      p.dirty_cash = p.dirtyCash;
      return p;
    });
  }

  async function adminGetPlayer(username) {
    if (!username) return null;
    const cleanUser = String(username).replace(/^@/, '').trim();
    const rows = await _api(`players?username=ilike.${encodeURIComponent(cleanUser)}&order=last_seen.desc&select=*`);
    if (!rows || rows.length === 0) return null;
    const r = rows[0];
    let stateObj = {};
    if (r.state) {
      if (typeof r.state === 'object') stateObj = { ...r.state };
      else if (typeof r.state === 'string') {
        try { stateObj = JSON.parse(r.state); } catch(e) {}
      }
    }
    const p = { ...stateObj };
    p.state = stateObj;
    p.username = r.username;
    p.pin = r.pin;
    p.cash = Number(r.cash !== undefined ? r.cash : (stateObj.cash || 0));
    p.bank = Number(r.bank !== undefined ? r.bank : (stateObj.bank || 0));
    p.dirtyCash = Number(r.dirty_cash !== undefined ? r.dirty_cash : (stateObj.dirtyCash || 0));
    p.netWorth = Number(r.net_worth !== undefined ? r.net_worth : (stateObj.netWorth || 0));
    p.xp = Number(r.xp !== undefined ? r.xp : (stateObj.xp || 0));
    p.title = r.title || stateObj.title || 'عامل مبتدئ';
    p.jobId = r.job_id || stateObj.jobId || 'worker';
    p.isAdmin = r.is_admin === true || stateObj.isAdmin === true;
    p.isBanned = r.is_banned === true || stateObj.isBanned === true;
    p.jailTimer = Number(r.jail_timer !== undefined ? r.jail_timer : (stateObj.jailTimer || 0));
    p.totalTaxesPaid = Number(r.total_taxes_paid !== undefined ? r.total_taxes_paid : (stateObj.totalTaxesPaid || 0));
    p.afkManagerExpiresAt = Number(r.afk_manager_expires_at !== undefined ? r.afk_manager_expires_at : (stateObj.afkManagerExpiresAt || 0));
    const seenTs = Number(r.last_seen || stateObj.lastSeen || stateObj.lastActiveTimestamp || 0);
    p.lastSeen = seenTs;
    p.lastActiveTimestamp = seenTs;
    p.last_seen = seenTs;
    p.createdAt = Number(r.created_at || stateObj.createdAt || 0);
    p.is_admin = p.isAdmin;
    p.is_banned = p.isBanned;
    p.jail_timer = p.jailTimer;
    p.net_worth = p.netWorth;
    p.dirty_cash = p.dirtyCash;
    return p;
  }

  async function adminSavePlayer(username, updates) {
    const cleanUser = String(username || '').replace(/^@/, '').trim();
    if (!cleanUser) return false;

    // 1. Fetch freshest existing state to prevent data loss on partial updates
    const existing = await adminGetPlayer(cleanUser) || {};
    const existingState = (existing.state && typeof existing.state === 'object') ? existing.state : existing;

    const payload = {};
    if (updates.cash !== undefined) payload.cash = Number(updates.cash);
    if (updates.bank !== undefined) payload.bank = Number(updates.bank);
    if (updates.dirtyCash !== undefined) payload.dirty_cash = Number(updates.dirtyCash);
    if (updates.netWorth !== undefined) payload.net_worth = Number(updates.netWorth);
    if (updates.xp !== undefined) payload.xp = Number(updates.xp);
    if (updates.gold !== undefined) payload.gold = Math.max(0, Number(updates.gold));
    if (updates.title !== undefined) payload.title = updates.title;
    if (updates.jobId !== undefined) payload.job_id = updates.jobId;
    if (updates.isAdmin !== undefined) payload.is_admin = Boolean(updates.isAdmin);
    if (updates.isBanned !== undefined) payload.is_banned = Boolean(updates.isBanned);
    if (updates.jailTimer !== undefined) payload.jail_timer = Number(updates.jailTimer);
    if (updates.pin !== undefined) payload.pin = updates.pin;

    // 2. Prepare comprehensive state payload merging existing and new updates
    const updatesState = (updates.state && typeof updates.state === 'object') ? updates.state : updates;
    const stateObj = { ...existingState, ...updatesState };

    // Preserve seasonBadge if present in existing state and not intentionally changed
    if (existingState.seasonBadge && (updatesState.seasonBadge === undefined || updatesState.seasonBadge === '')) {
      stateObj.seasonBadge = existingState.seasonBadge;
    }

    // Clear any past reset flags
    stateObj.isReset = false;
    delete stateObj.resetTimestamp;
    stateObj.username = cleanUser;

    if (payload.cash !== undefined) stateObj.cash = payload.cash;
    if (payload.bank !== undefined) stateObj.bank = payload.bank;
    if (payload.dirty_cash !== undefined) stateObj.dirtyCash = payload.dirty_cash;
    if (payload.net_worth !== undefined) stateObj.netWorth = payload.net_worth;
    if (payload.xp !== undefined) stateObj.xp = payload.xp;
    if (payload.gold !== undefined) stateObj.gold = payload.gold;
    if (payload.title !== undefined) stateObj.title = payload.title;
    if (payload.job_id !== undefined) stateObj.jobId = payload.job_id;
    if (payload.is_admin !== undefined) stateObj.isAdmin = payload.is_admin;
    if (payload.jail_timer !== undefined) stateObj.jailTimer = payload.jail_timer;

    const now = Number(updates.adminModifiedTimestamp) || Date.now();
    stateObj.adminModifiedTimestamp = now;
    payload.state = stateObj;
    payload.admin_modified_timestamp = now;

    await _api(`players?username=ilike.${encodeURIComponent(cleanUser)}`, {
      method: 'PATCH',
      body: JSON.stringify(payload)
    });

    // Dispatch instant real-time sync notification via mailbox so player receives update immediately (< 1s)
    try {
      await sendMail('إدارة اللعبة (Admin)', cleanUser, 'admin_sync', {
        timestamp: now,
        reason: 'admin_state_saved'
      });
    } catch (_) {}

    return true;
  }

