  async function adminRebuildLeaderboard() {
    const now = Date.now();
    const rows = await _api('players?select=username,cash,bank,net_worth,title,job_id,is_admin,is_banned,state&is_banned=eq.false&is_admin=eq.false&username=not.in.(newu,khaled,Khaled,خالد,rasalmal,rasalmal1,rasalmal2,Rasalmal,Rasalmal1,Rasalmal2,asd,Asd,ASD,7ablas,7Ablas,osos,Osos,OSOS,tito2761,Tito2761,TITO2761)&order=net_worth.desc&limit=35');

    const topPlayers = (rows || [])
      .filter(r => !isHiddenPlayer(r.username, r.is_admin))
      .slice(0, 25)
      .map(r => {
      let pState = r.state;
      if (typeof pState === 'string') {
        try { pState = JSON.parse(pState); } catch(e) { pState = {}; }
      }
      pState = pState || {};
      const isFb = pState.facebookVerified === true || (Array.isArray(pState.badges) && pState.badges.includes('facebook'));

      return {
        username: r.username,
        cash: Number(r.cash || 0),
        bank: Number(r.bank || 0),
        netWorth: Number(r.net_worth || 0),
        net_worth: Number(r.net_worth || 0),
        title: r.title || 'عامل مبتدئ',
        jobId: r.job_id || 'worker',
        isAdmin: r.is_admin === true,
        seasonBadge: pState.seasonBadge || '',
        customBadge: pState.customBadge || '',
        facebookVerified: isFb
      };
    });

    _leaderboardMeta = {
      updatedAt: now,
      nextUpdateAt: now + (60 * 60 * 1000),
      cycleMinutes: 60
    };

    const docPayload = {
      id: 'leaderboard',
      data: {
        updatedAt: _leaderboardMeta.updatedAt,
        nextUpdateAt: _leaderboardMeta.nextUpdateAt,
        cycleMinutes: 60,
        topPlayers: topPlayers
      },
      updated_at: now
    };

    await _api('globals', {
      method: 'POST',
      headers: { 'Prefer': 'resolution=merge-duplicates' },
      body: JSON.stringify(docPayload)
    });

    await _api('globals', {
      method: 'POST',
      headers: { 'Prefer': 'resolution=merge-duplicates' },
      body: JSON.stringify({
        id: 'hourly_leaderboard',
        data: { timestamp: now, topPlayers: topPlayers },
        updated_at: now
      })
    });

    _leaderboardCache = topPlayers;
    _lastLeaderboardFetchTime = now;

    return topPlayers;
  }

