  function getTodayDateString() {
    const ts = getTrustedNow();
    // Use fixed Cairo/Middle East timezone (UTC+3) to guarantee 100% consistency across devices and timezones
    const cairoDate = new Date(ts + (3 * 3600 * 1000));
    const year = cairoDate.getUTCFullYear();
    const month = String(cairoDate.getUTCMonth() + 1).padStart(2, '0');
    const day = String(cairoDate.getUTCDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  function getDailyResetRemainingSeconds() {
    const ts = getTrustedNow();
    const cairoNow = new Date(ts + (3 * 3600 * 1000));
    const cairoMidnight = new Date(Date.UTC(cairoNow.getUTCFullYear(), cairoNow.getUTCMonth(), cairoNow.getUTCDate() + 1, 0, 0, 0));
    return Math.max(0, Math.floor((cairoMidnight.getTime() - (ts + (3 * 3600 * 1000))) / 1000));
  }

  function ensureDailyQuests() {
    if (!state) return;
    const today = getTodayDateString();
    if (!state.dailyQuests || state.dailyQuests.date !== today || !Array.isArray(state.dailyQuests.quests)) {
      // Check if local cache has today's quests before generating brand new ones
      if (activeUsername && typeof AppDB !== 'undefined' && AppDB.getDecryptedLocalState) {
        try {
          const cached = AppDB.getDecryptedLocalState(`rasalmal_state_${activeUsername}`);
          if (cached && cached.dailyQuests && cached.dailyQuests.date === today && Array.isArray(cached.dailyQuests.quests)) {
            state.dailyQuests = JSON.parse(JSON.stringify(cached.dailyQuests));
            return;
          }
        } catch (e) {}
      }

      const netWorth = (typeof calculateNetWorth === 'function') ? calculateNetWorth() : (state.netWorth || 400);
      // Balanced reward scaling: Starts at ~350 EGP, scales gradually with sqrt of wealth, capped at 35,000 EGP per quest
      const baseCash = Math.max(350, Math.round(350 + Math.min(35000, Math.sqrt(Math.max(0, netWorth)) * 1.2)));
      const baseXP = Math.max(20, Math.round(Math.min(250, 15 + Math.log10(Math.max(10, netWorth)) * 10)));

      state.dailyQuests = {
        date: today,
        grandBonusClaimed: false,
        quests: DAILY_QUEST_TEMPLATES.map(t => ({
          id: t.id,
          title: t.title,
          desc: t.desc,
          target: t.target,
          progress: 0,
          completed: false,
          claimed: false,
          cashReward: baseCash,
          xpReward: baseXP,
          icon: t.icon,
          category: t.category
        }))
      };
    } else {
      // Migrate legacy casino_play quest to trade_shipment
      const casinoIdx = state.dailyQuests.quests.findIndex(q => q && q.id === 'casino_play');
      if (casinoIdx !== -1) {
        const netWorth = (typeof calculateNetWorth === 'function') ? calculateNetWorth() : (state.netWorth || 400);
        const baseCash = Math.max(350, Math.round(350 + Math.min(35000, Math.sqrt(Math.max(0, netWorth)) * 1.2)));
        const baseXP = Math.max(20, Math.round(Math.min(250, 15 + Math.log10(Math.max(10, netWorth)) * 10)));
        state.dailyQuests.quests[casinoIdx] = {
          id: 'trade_shipment',
          title: 'خبير التجارة الدولية',
          desc: 'أكمل شحنة تصدير أو استيراد في شركة التجارة',
          target: 1,
          progress: 0,
          completed: false,
          claimed: false,
          cashReward: baseCash,
          xpReward: baseXP,
          icon: 'fa-ship',
          category: 'trade'
        };
      }

      // Re-normalize if existing active quests have obsolete overpowered rewards (> 50,000 EGP)
      if (state.dailyQuests.quests.some(q => q.cashReward > 50000)) {
        const netWorth = (typeof calculateNetWorth === 'function') ? calculateNetWorth() : (state.netWorth || 400);
        const baseCash = Math.max(350, Math.round(350 + Math.min(35000, Math.sqrt(Math.max(0, netWorth)) * 1.2)));
        const baseXP = Math.max(20, Math.round(Math.min(250, 15 + Math.log10(Math.max(10, netWorth)) * 10)));
        state.dailyQuests.quests.forEach(q => {
          if (!q.claimed) {
            q.cashReward = baseCash;
            q.xpReward = baseXP;
          }
        });
      }
    }
  }

  function trackDailyQuestProgress(questId, amount = 1) {
    if (!state) return;
    ensureDailyQuests();
    if (!state.dailyQuests || !Array.isArray(state.dailyQuests.quests)) return;
    const q = state.dailyQuests.quests.find(item => item.id === questId);
    if (q && !q.completed) {
      q.progress = Math.min(q.target, (q.progress || 0) + amount);
      if (q.progress >= q.target) {
        q.completed = true;
      }
    }
  }

  function claimDailyQuestReward(questId) {
    ensureDailyQuests();
    if (!state.dailyQuests || !Array.isArray(state.dailyQuests.quests)) {
      throw new Error("بيانات المهام اليومية غير متوفرة.");
    }
    const q = state.dailyQuests.quests.find(item => item.id === questId);
    if (!q) throw new Error("المهمة المطلوبة غير موجودة.");
    if (!q.completed) throw new Error("لم تكتمل أهداف هذه المهمة بعد.");
    if (q.claimed) throw new Error("تم استلام مكافأة هذه المهمة بالفعل لهذا اليوم.");

    q.claimed = true;
    state.cash = (state.cash || 0) + q.cashReward;
    state.xp = (state.xp || 0) + q.xpReward;

    recordPlayerActivity('استلام مكافأة مهمة يومية',`استلام مكافأة:"${q.title}" (+${q.cashReward.toLocaleString('ar-EG')} EGP, +${q.xpReward} XP)`,'reward');
    state.netWorth = calculateNetWorth();
    state.title = getAppropriateTitle(state.netWorth, state.xp);
    if (activeUsername) {
      forceSaveState(true);
    }

    return {
      cash: q.cashReward,
      xp: q.xpReward,
      quest: q
    };
  }

  function claimGrandDailyBonus() {
    ensureDailyQuests();
    if (!state.dailyQuests || !Array.isArray(state.dailyQuests.quests)) {
      throw new Error("بيانات المهام اليومية غير متوفرة.");
    }
    if (state.dailyQuests.grandBonusClaimed) {
      throw new Error("تم فتح واستلام صندوق المكافأة الكبرى لهذا اليوم بالفعل.");
    }

    const allClaimed = state.dailyQuests.quests.every(q => q.claimed);
    if (!allClaimed) {
      throw new Error("يجب إكمال واستلام مكافآت جميع المهام الخمس أولاً لفتح الصندوق الأكبر!");
    }

    const sampleQ = state.dailyQuests.quests[0];
    const grandCash = Math.round((sampleQ ? sampleQ.cashReward : 500) * 2);
    const grandXP = Math.round((sampleQ ? sampleQ.xpReward : 20) * 2);

    state.dailyQuests.grandBonusClaimed = true;
    state.cash = (state.cash || 0) + grandCash;
    state.xp = (state.xp || 0) + grandXP;

    recordPlayerActivity('فتح صندوق المكافأة الكبرى اليومي',`فتح صندوق المكافأة الكبرى! (+${grandCash.toLocaleString('ar-EG')} EGP, +${grandXP} XP)`,'reward');
    state.netWorth = calculateNetWorth();
    state.title = getAppropriateTitle(state.netWorth, state.xp);
    if (activeUsername) {
      forceSaveState(true);
    }

    return {
      cash: grandCash,
      xp: grandXP
    };
  }

