    if (startMenu) startMenu.classList.add('hidden');
    if (chatDrawer) chatDrawer.classList.add('hidden');
    if (chatTrigger) chatTrigger.classList.add('hidden');

    // Show ban overlay
    let banOverlay = document.getElementById('ban-overlay');
