  // ── SUB-PANEL 3: Livestock & Poultry Ranch ──
  function renderFarmLivestock(farmInfo) {
    const farm = farmInfo.farm;
    const lConfig = farmInfo.livestockConfig || (GameEngine && GameEngine.FARM_LIVESTOCK_CONFIG) || {};

    const btnApplyCompost = document.getElementById('btn-farm-apply-compost');
    if (btnApplyCompost) {
      btnApplyCompost.onclick = () => {
        try {
          const res = GameEngine.applyCompostFertilizer();
          playMenuSound('success');
          showToast('تسميد عضوي مكثف 🌿', `تم تسريع نمو ${res.plotsBoosted} أحواض زراعية بنسبة 35% فوراً! المتبقي: ${res.remainingCompost} سماد.`, 'success');
          renderFarmPanel();
          renderStatsBar();
        } catch (e) {
          playMenuSound('error');
          showToast('تعذر التسميد', e.message, 'error');
        }
      };
    }

    const btnSellAllLivestock = document.getElementById('btn-farm-sell-all-livestock');
    if (btnSellAllLivestock) {
      btnSellAllLivestock.onclick = () => {
        playMenuSound('click');
        switchFarmSubtab('contracts');
        const cPanel = document.getElementById('farm-subpanel-contracts');
        if (cPanel) cPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
      };
    }

    // Livestock Facilities Cards Grid
    const facilitiesGrid = document.getElementById('farm-livestock-facilities-grid');
    if (facilitiesGrid) {
      const cowDef = lConfig.cow || { cost: 25000, maxCount: 8, name: 'أبقار هولشتاين الحلوب' };
      const chkDef = lConfig.chicken || { cost: 8000, maxCount: 10, name: 'عنابر الدجاج البياض' };

      const cowsOwned = Number((farm.livestock && farm.livestock.cows) || 0);
      const maxCows = cowDef.maxCount || 8;
      const cowCost = cowDef.cost || 25000;

      const chickensOwned = Number((farm.livestock && farm.livestock.chickens) || 0);
      const maxChickens = chkDef.maxCount || 10;
      const chickenCost = chkDef.cost || 8000;

      facilitiesGrid.innerHTML = `
        <!-- 1. Dairy Cows Ranch -->
        <div class="p-5 rounded-2xl bg-slate-900/80 border border-emerald-500/30 hover:border-emerald-500/60 transition flex flex-col justify-between gap-4 shadow-xl">
          <div class="flex items-start justify-between gap-3">
            <div class="flex items-center gap-3">
              <div class="w-12 h-12 rounded-2xl bg-emerald-500/20 border border-emerald-500/40 flex items-center justify-center text-2xl text-emerald-400 shrink-0">
                <i class="fa-solid fa-cow"></i>
              </div>
              <div>
                <h4 class="font-black text-white text-sm">${cowDef.name}</h4>
                <p class="text-[11px] text-slate-400 mt-0.5">إنتاج دوري للحليب الطازج والسماد العضوي الثمين للأحواض.</p>
              </div>
            </div>
            <span class="px-2.5 py-1 rounded-full bg-emerald-500/20 text-emerald-300 font-bold text-xs border border-emerald-500/30 shrink-0">
              ${cowsOwned} / ${maxCows} بقرة
            </span>
          </div>

          <div class="grid grid-cols-2 gap-2 p-3 bg-slate-950/70 rounded-xl border border-slate-800 text-[11px]">
            <div>
              <span class="text-slate-400 block text-[10px]">الإنتاج الدوري (كل ${cowDef.produceIntervalSeconds || 90}ث)</span>
              <span class="font-bold text-emerald-400">+2 لتر حليب (وسماد عضوي كل 4د)</span>
            </div>
            <div>
              <span class="text-slate-400 block text-[10px]">سعر شراء الرأس</span>
              <span class="font-mono font-bold text-yellow-400">${cowCost.toLocaleString()} EGP</span>
            </div>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <button ${cowsOwned >= maxCows ? 'disabled' : 'onclick="window.UI?.buyLivestock(\'cow\', 1)"'} type="button"
              class="py-2 px-3 rounded-xl text-xs font-bold transition flex items-center justify-center gap-1.5 cursor-pointer ${cowsOwned < maxCows ? 'bg-emerald-500/20 hover:bg-emerald-500 text-emerald-300 hover:text-slate-950 border border-emerald-500/40 active:scale-95' : 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'}">
              <i class="fa-solid fa-plus text-xs"></i>
              <span>+1 بقرة (${cowCost.toLocaleString()})</span>
            </button>
            <button ${cowsOwned + 5 > maxCows ? 'disabled' : 'onclick="window.UI?.buyLivestock(\'cow\', 5)"'} type="button"
              class="py-2 px-3 rounded-xl text-xs font-black transition flex items-center justify-center gap-1.5 cursor-pointer ${cowsOwned + 5 <= maxCows ? 'bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white shadow active:scale-95' : 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'}">
              <i class="fa-solid fa-bolt text-xs"></i>
              <span>+5 أبقار (${(cowCost * 5).toLocaleString()})</span>
            </button>
          </div>
        </div>

        <!-- 2. Poultry Chickens Farm -->
        <div class="p-5 rounded-2xl bg-slate-900/80 border border-cyan-500/30 hover:border-cyan-500/60 transition flex flex-col justify-between gap-4 shadow-xl">
          <div class="flex items-start justify-between gap-3">
            <div class="flex items-center gap-3">
              <div class="w-12 h-12 rounded-2xl bg-cyan-500/20 border border-cyan-500/40 flex items-center justify-center text-2xl text-cyan-400 shrink-0">
                <i class="fa-solid fa-egg"></i>
              </div>
              <div>
                <h4 class="font-black text-white text-sm">${chkDef.name}</h4>
                <p class="text-[11px] text-slate-400 mt-0.5">إنتاج كراتين بيض المائدة الطازج عالي الطلب في عقود التوريد والمطاعم.</p>
              </div>
            </div>
            <span class="px-2.5 py-1 rounded-full bg-cyan-500/20 text-cyan-300 font-bold text-xs border border-cyan-500/30 shrink-0">
              ${chickensOwned} / ${maxChickens} عنابر
            </span>
          </div>

          <div class="grid grid-cols-2 gap-2 p-3 bg-slate-950/70 rounded-xl border border-slate-800 text-[11px]">
            <div>
              <span class="text-slate-400 block text-[10px]">الإنتاج الدوري (كل ${chkDef.produceIntervalSeconds || 120}ث)</span>
              <span class="font-bold text-cyan-400">+${chkDef.eggYield || 1} كرتونة بيض / عنبر</span>
            </div>
            <div>
              <span class="text-slate-400 block text-[10px]">سعر شراء العنبر</span>
              <span class="font-mono font-bold text-yellow-400">${chickenCost.toLocaleString()} EGP</span>
            </div>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <button ${chickensOwned >= maxChickens ? 'disabled' : 'onclick="window.UI?.buyLivestock(\'chicken\', 1)"'} type="button"
              class="py-2 px-3 rounded-xl text-xs font-bold transition flex items-center justify-center gap-1.5 cursor-pointer ${chickensOwned < maxChickens ? 'bg-cyan-500/20 hover:bg-cyan-500 text-cyan-300 hover:text-slate-950 border border-cyan-500/40 active:scale-95' : 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'}">
              <i class="fa-solid fa-plus text-xs"></i>
              <span>+1 عنبر (${chickenCost.toLocaleString()})</span>
            </button>
            <button ${chickensOwned + 5 > maxChickens ? 'disabled' : 'onclick="window.UI?.buyLivestock(\'chicken\', 5)"'} type="button"
              class="py-2 px-3 rounded-xl text-xs font-black transition flex items-center justify-center gap-1.5 cursor-pointer ${chickensOwned + 5 <= maxChickens ? 'bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white shadow active:scale-95' : 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'}">
              <i class="fa-solid fa-bolt text-xs"></i>
              <span>+5 عنابر (${(chickenCost * 5).toLocaleString()})</span>
            </button>
          </div>
        </div>
      `;
    }

    // Livestock Produce Grid
    const produceGrid = document.getElementById('farm-livestock-produce-grid');
    if (produceGrid) {
      const cowDef = lConfig.cow || { sellPrice: 45, maxCompost: 25 };
      const chkDef = lConfig.chicken || { sellPrice: 15 };

      const milk = Number((farm.livestock && farm.livestock.milk) || 0);
      const eggs = Number((farm.livestock && farm.livestock.eggs) || 0);
      const compost = Number((farm.livestock && farm.livestock.compost) || 0);
      const maxCompost = cowDef.maxCompost || 25;
      const cowsOwned = Number((farm.livestock && farm.livestock.cows) || 0);

      produceGrid.innerHTML = `
        <!-- Milk -->
        <div class="p-4 rounded-2xl bg-slate-900/70 border border-slate-800 flex flex-col justify-between gap-3 shadow">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 rounded-xl bg-cyan-500/20 border border-cyan-500/40 flex items-center justify-center text-cyan-300 text-lg shrink-0">
              <i class="fa-solid fa-bottle-water"></i>
            </div>
            <div>
              <h4 class="font-black text-white text-xs">حليب أبقار طازج</h4>
              <p class="text-[10px] text-slate-400 mt-0.5">${cowDef.sellPrice} EGP / لتر</p>
            </div>
          </div>
          <div class="flex justify-between items-center text-xs font-bold pt-1 border-t border-slate-800/80">
            <span class="text-slate-400">المخزون المتوفر:</span>
            <span class="numbers-font text-cyan-300 font-black text-sm">${milk.toLocaleString()} لتر</span>
          </div>
          <div class="grid grid-cols-5 gap-1.5 pt-1">
            <button onclick="window.UI?.switchFarmSubtab('contracts')" type="button"
              class="col-span-3 py-1.5 px-2 rounded-xl text-xs font-black transition cursor-pointer bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white shadow active:scale-95 flex items-center justify-center gap-1">
              <i class="fa-solid fa-file-contract text-[10px]"></i>
              <span>عقود B2B</span>
            </button>
            <button ${milk <= 0 ? 'disabled' : `onclick="window.UI?.emergencyDumpLivestockProduce('milk')"`} type="button"
              title="تسييل اضطراري بسعر التكلفة الرمزية (5 EGP)"
              class="col-span-2 py-1.5 px-1 rounded-xl text-[9.5px] font-bold transition flex items-center justify-center gap-1 ${milk > 0 ? 'bg-slate-800/90 hover:bg-rose-950/60 hover:text-rose-300 text-slate-400 border border-slate-700/80 cursor-pointer active:scale-95' : 'bg-slate-900 text-slate-600 border border-slate-800/50 cursor-not-allowed'}">
              <i class="fa-solid fa-recycle text-[9px]"></i>
              <span>تسييل تكلفة</span>
            </button>
          </div>
        </div>

        <!-- Eggs -->
        <div class="p-4 rounded-2xl bg-slate-900/70 border border-slate-800 flex flex-col justify-between gap-3 shadow">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 rounded-xl bg-amber-500/20 border border-amber-500/40 flex items-center justify-center text-amber-300 text-lg shrink-0">
              <i class="fa-solid fa-egg"></i>
            </div>
            <div>
              <h4 class="font-black text-white text-xs">كراتين بيض مائدة</h4>
              <p class="text-[10px] text-slate-400 mt-0.5">${chkDef.sellPrice} EGP / كرتونة</p>
            </div>
          </div>
          <div class="flex justify-between items-center text-xs font-bold pt-1 border-t border-slate-800/80">
            <span class="text-slate-400">المخزون المتوفر:</span>
            <span class="numbers-font text-amber-300 font-black text-sm">${eggs.toLocaleString()} كرتونة</span>
          </div>
          <div class="grid grid-cols-5 gap-1.5 pt-1">
            <button onclick="window.UI?.switchFarmSubtab('contracts')" type="button"
              class="col-span-3 py-1.5 px-2 rounded-xl text-xs font-black transition cursor-pointer bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white shadow active:scale-95 flex items-center justify-center gap-1">
              <i class="fa-solid fa-file-contract text-[10px]"></i>
              <span>عقود B2B</span>
            </button>
            <button ${eggs <= 0 ? 'disabled' : `onclick="window.UI?.emergencyDumpLivestockProduce('eggs')"`} type="button"
              title="تسييل اضطراري بسعر التكلفة الرمزية (5 EGP)"
              class="col-span-2 py-1.5 px-1 rounded-xl text-[9.5px] font-bold transition flex items-center justify-center gap-1 ${eggs > 0 ? 'bg-slate-800/90 hover:bg-rose-950/60 hover:text-rose-300 text-slate-400 border border-slate-700/80 cursor-pointer active:scale-95' : 'bg-slate-900 text-slate-600 border border-slate-800/50 cursor-not-allowed'}">
              <i class="fa-solid fa-recycle text-[9px]"></i>
              <span>تسييل تكلفة</span>
            </button>
          </div>
        </div>

        <!-- Compost Booster -->
        <div class="p-4 rounded-2xl bg-slate-900/70 border border-emerald-500/30 flex flex-col justify-between gap-3 shadow">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 rounded-xl bg-emerald-500/20 border border-emerald-500/40 flex items-center justify-center text-emerald-400 text-lg shrink-0">
              <i class="fa-solid fa-leaf"></i>
            </div>
            <div>
              <div class="flex items-center gap-1.5">
                <h4 class="font-black text-white text-xs">سماد عضوي طبيعي</h4>
                ${compost >= maxCompost ? '<span class="text-[8.5px] px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-300 font-bold border border-amber-500/30 shrink-0">الحفرة ممتلئة</span>' : ''}
              </div>
              <p class="text-[10px] text-emerald-300 mt-0.5">تسريع نمو الأحواض 35% فوراً!</p>
            </div>
          </div>
          
          <div class="space-y-1 pt-1 border-t border-slate-800/80">
            <div class="flex justify-between items-center text-xs font-bold">
              <span class="text-slate-400">سعة حفرة التخمير:</span>
              <span class="numbers-font ${compost >= maxCompost ? 'text-amber-400' : 'text-emerald-300'} font-black text-sm">${compost.toLocaleString()} / ${maxCompost} سماد</span>
            </div>
            <div class="w-full bg-slate-950 h-1.5 rounded-full overflow-hidden border border-slate-800">
              <div class="h-full rounded-full transition-all duration-300 ${compost >= maxCompost ? 'bg-amber-500' : 'bg-emerald-500'}" style="width: ${Math.min(100, Math.round((compost / maxCompost) * 100))}%"></div>
            </div>
            <div class="flex justify-between items-center text-[9px] text-slate-500 font-medium">
              <span>دورة التخمير: 4 دقائق</span>
              <span class="${cowsOwned > 0 ? (compost >= maxCompost ? 'text-amber-400' : 'text-emerald-400') : 'text-slate-500'} font-bold">
                ${cowsOwned > 0 ? (compost >= maxCompost ? 'الإنتاج متوقف (ممتلئ)' : 'تخمير (+ ' + (cowsOwned >= 7 ? 3 : (cowsOwned >= 4 ? 2 : 1)) + ' سماد)') : 'يلزم تربية أبقار'}
              </span>
            </div>
          </div>

          <button ${compost < 5 ? 'disabled' : 'onclick="window.UI?.applyCompostFertilizer()"'} type="button"
            class="w-full py-2 rounded-xl text-xs font-black transition cursor-pointer ${compost >= 5 ? 'bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-slate-950 shadow active:scale-95' : 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'}">
            ${compost >= 5 ? 'استخدام السماد (خصم 5 وحدات)' : 'يلزم 5 وحدات سماد (' + compost + '/5)'}
          </button>
        </div>
      `;
    }
  }

  // ── SUB-PANEL 4: B2B Supply Contracts Board (50 Daily Contracts) ──
  let _activeContractFilter = 'all';
  let _contractSearchQuery = '';

  function renderFarmContracts(farmInfo) {
    const farm = farmInfo.farm;
    const contractsData = farm.contracts || {};
    const allContracts = (farmInfo.contracts) || (contractsData.active) || [];
    const now = (typeof getTrustedNowUI === 'function') ? getTrustedNowUI() : Date.now();

    // 1. Update Header Statistics
    const repStat = document.getElementById('farm-contracts-rep-stat');
    if (repStat) {
      repStat.textContent = `${(contractsData.reputation || 0).toLocaleString()} XP`;
    }

    const completedStat = document.getElementById('farm-contracts-completed-stat');
    if (completedStat) {
      const completedCount = allContracts.filter(c => c && c.fulfilled).length;
      completedStat.textContent = `${completedCount} / ${allContracts.length || 50}`;
    }

    const revenueStat = document.getElementById('farm-contracts-revenue-stat');
    if (revenueStat) {
      const dailyLiq = farmInfo.dailyLiquidation || (GameEngine && GameEngine.getFarmDailyLiquidationInfo ? GameEngine.getFarmDailyLiquidationInfo(farm) : null);
      if (dailyLiq && !dailyLiq.isUnlimited) {
        revenueStat.textContent = `${(dailyLiq.totalLiquidated || 0).toLocaleString()} / ${dailyLiq.cap.toLocaleString()} EGP`;
      } else {
        revenueStat.textContent = `${(contractsData.revenueToday || 0).toLocaleString()} EGP`;
      }
    }

    // 2. Calculate Filter Counts
    let readyCount = 0;
    let fulfilledCount = 0;

    allContracts.forEach(c => {
      if (!c) return;
      if (c.fulfilled) {
        fulfilledCount++;
        return;
      }
      let avail = 0;
      if (c.itemType === 'crop') {
        avail = Number((farm.inventory && farm.inventory[c.itemId]) || 0);
      } else if (c.itemType === 'processed') {
        avail = Number((farm.processing && farm.processing.storage && farm.processing.storage[c.itemId]) || 0);
      } else if (c.itemType === 'livestock') {
        avail = Number((farm.livestock && farm.livestock[c.itemId]) || 0);
      }
      if (avail >= c.quantityNeeded) {
        readyCount++;
      }
    });

    const filterAllEl = document.getElementById('filter-count-all');
    if (filterAllEl) filterAllEl.textContent = allContracts.length || 50;

    const filterReadyEl = document.getElementById('filter-count-ready');
    if (filterReadyEl) filterReadyEl.textContent = readyCount;

    const filterFulfilledEl = document.getElementById('filter-count-fulfilled');
    if (filterFulfilledEl) filterFulfilledEl.textContent = fulfilledCount;

    // 3. Bind Filter Buttons & Search Input
    const filterContainer = document.getElementById('farm-contracts-filters');
    if (filterContainer && !filterContainer.dataset.bound) {
      filterContainer.dataset.bound = 'true';
      filterContainer.querySelectorAll('.farm-contract-filter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          playMenuSound('click');
          _activeContractFilter = btn.getAttribute('data-contract-filter') || 'all';
          // Update button styles
          filterContainer.querySelectorAll('.farm-contract-filter-btn').forEach(b => {
            const f = b.getAttribute('data-contract-filter');
            if (f === _activeContractFilter) {
              b.className = 'farm-contract-filter-btn px-3 py-1.5 rounded-xl font-bold text-xs transition cursor-pointer bg-purple-500/20 text-purple-300 border border-purple-500/40';
            } else {
              b.className = 'farm-contract-filter-btn px-3 py-1.5 rounded-xl font-bold text-xs transition cursor-pointer bg-slate-900/60 text-slate-400 hover:text-white border border-slate-800';
            }
          });
          renderFarmContracts(GameEngine.getFarmState());
        });
      });
    }

    const searchInput = document.getElementById('farm-contracts-search');
    if (searchInput && !searchInput.dataset.bound) {
      searchInput.dataset.bound = 'true';
      searchInput.addEventListener('input', (e) => {
        _contractSearchQuery = (e.target.value || '').trim().toLowerCase();
        renderFarmContracts(GameEngine.getFarmState());
      });
    }

    // 4. Filter Contracts
    let filtered = allContracts.filter(c => {
      if (!c) return false;

      let available = 0;
      if (c.itemType === 'crop') {
        available = Number((farm.inventory && farm.inventory[c.itemId]) || 0);
      } else if (c.itemType === 'processed') {
        available = Number((farm.processing && farm.processing.storage && farm.processing.storage[c.itemId]) || 0);
      } else if (c.itemType === 'livestock') {
        available = Number((farm.livestock && farm.livestock[c.itemId]) || 0);
      }
      const canFulfill = available >= c.quantityNeeded;

      // Status/Type filter
      if (_activeContractFilter === 'ready' && (!canFulfill || c.fulfilled)) return false;
      if (_activeContractFilter === 'fulfilled' && !c.fulfilled) return false;
      if (_activeContractFilter === 'crop' && c.itemType !== 'crop') return false;
      if (_activeContractFilter === 'processed' && c.itemType !== 'processed') return false;
      if (_activeContractFilter === 'livestock' && c.itemType !== 'livestock') return false;

      // Search Query filter
      if (_contractSearchQuery) {
        const matchName = (c.itemName || '').toLowerCase().includes(_contractSearchQuery);
        const matchClient = (c.clientName || '').toLowerCase().includes(_contractSearchQuery);
        if (!matchName && !matchClient) return false;
      }

      return true;
    });

    // Sort: Ready contracts first, then unfulfilled, then fulfilled last
    filtered.sort((a, b) => {
      if (a.fulfilled && !b.fulfilled) return 1;
      if (!a.fulfilled && b.fulfilled) return -1;
      return 0;
    });

    const contractsGrid = document.getElementById('farm-contracts-grid');
    if (contractsGrid) {
      if (filtered.length === 0) {
        contractsGrid.innerHTML = `
          <div class="col-span-full py-12 text-center space-y-3 text-slate-500">
            <i class="fa-solid fa-file-circle-question text-4xl text-purple-400/40"></i>
            <p class="text-xs font-bold">لا توجد عقود مطابقة للتصفية الحالية!</p>
            <button onclick="document.querySelector('.farm-contract-filter-btn[data-contract-filter=\\'all\\']')?.click()" class="text-xs text-purple-400 underline font-bold cursor-pointer">
              عرض جميع العقود (50 عقد)
            </button>
          </div>
        `;
        return;
      }

      const dailyLiq = farmInfo.dailyLiquidation || (GameEngine && GameEngine.getFarmDailyLiquidationInfo ? GameEngine.getFarmDailyLiquidationInfo(farm) : { isUnlimited: true, remaining: Infinity });

      let cHtml = '';
      filtered.forEach((c, idx) => {
        const reqs = (Array.isArray(c.requirements) && c.requirements.length > 0)
          ? c.requirements
          : [{
              itemType: c.itemType,
              itemId: c.itemId,
              itemName: c.itemName,
              itemIcon: c.itemIcon,
              quantityNeeded: c.quantityNeeded
            }];

        const reqStatusList = reqs.map(r => {
          let avail = 0;
          if (r.itemType === 'crop') {
            avail = Number((farm.inventory && farm.inventory[r.itemId]) || 0);
          } else if (r.itemType === 'processed') {
            avail = Number((farm.processing && farm.processing.storage && farm.processing.storage[r.itemId]) || 0);
          } else if (r.itemType === 'livestock') {
            avail = Number((farm.livestock && farm.livestock[r.itemId]) || 0);
          }
          const isReady = avail >= r.quantityNeeded;
          const pct = Math.min(100, Math.round((avail / r.quantityNeeded) * 100));
          return {
            ...r,
            available: avail,
            isReady,
            pct
          };
        });

        const canFulfillAll = reqStatusList.every(r => r.isReady);
        const missingCount = reqStatusList.filter(r => !r.isReady).length;
        const exceedsDailyCap = !dailyLiq.isUnlimited && !c.fulfilled && (c.payout > dailyLiq.remaining);

        cHtml += `
          <div class="p-5 rounded-2xl ${c.fulfilled ? 'bg-slate-950/60 border border-emerald-500/30 opacity-80' : (canFulfillAll ? 'bg-slate-900/90 border border-emerald-500/50 shadow-lg shadow-emerald-500/10' : 'bg-slate-900/80 border border-slate-800')} transition flex flex-col justify-between gap-4 relative overflow-hidden">
            
            ${canFulfillAll && !c.fulfilled ? '<div class="absolute -top-12 -right-12 w-28 h-28 bg-emerald-500/10 rounded-full blur-xl pointer-events-none"></div>' : ''}

            <div class="flex items-start justify-between gap-2 relative z-10">
              <div class="flex items-center gap-2.5">
                <div class="w-11 h-11 rounded-xl ${c.fulfilled ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30' : 'bg-purple-500/20 text-purple-300 border border-purple-500/30'} flex items-center justify-center text-xl shrink-0">
                  <i class="${c.clientIcon}"></i>
                </div>
                <div>
                  <div class="flex items-center gap-1.5">
                    <h4 class="font-black text-white text-xs">${c.clientName}</h4>
                    <span class="text-[9px] px-1.5 py-0.2 rounded bg-slate-800 text-slate-400 font-mono">#${c.contractNumber || (idx + 1)}</span>
                  </div>
                  <div class="flex items-center gap-1.5 mt-0.5">
                    <span class="text-[9px] px-2 py-0.5 rounded-full ${c.fulfilled ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30' : 'bg-purple-500/20 text-purple-300 border border-purple-500/30'} font-bold inline-block">
                      ${c.fulfilled ? 'تم التوريد بنجاح ✅' : (reqStatusList.length > 1 ? `طلبية مجمعة (${reqStatusList.length} أصناف)` : 'عقد توريد معتمد')}
                    </span>
                  </div>
                </div>
              </div>

              ${!c.fulfilled ? `
                <span class="text-[10px] font-bold text-sky-400 bg-sky-500/10 px-2.5 py-1 rounded-lg border border-sky-500/20 shrink-0 flex items-center gap-1">
                  <i class="fa-solid fa-infinity text-[10px]"></i>
                  <span>مفتوح دون وقت</span>
                </span>
              ` : `
                <span class="text-[10px] font-bold text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded-lg border border-emerald-500/20 shrink-0 flex items-center gap-1">
                  <i class="fa-solid fa-check mr-1"></i> مكتمل
                </span>
              `}
            </div>

            <div class="p-3 bg-slate-950/70 rounded-xl border border-slate-800 space-y-2.5 relative z-10">
              <div class="text-[11px] font-bold text-slate-400 flex items-center justify-between border-b border-slate-800/80 pb-1.5">
                <span>المطلوب توريده:</span>
                <span class="text-[10px] text-purple-300">${reqStatusList.length > 1 ? `${reqStatusList.length} متطلبات` : 'صنف واحد'}</span>
              </div>
              
              <div class="space-y-2">
                ${reqStatusList.map(r => `
                  <div class="space-y-1">
                    <div class="flex justify-between items-center text-xs">
                      <span class="font-bold text-white flex items-center gap-1.5 text-[11px]">
                        <i class="${r.itemIcon} text-amber-400 text-xs"></i>
                        <span>${r.itemName}</span>
                      </span>
                      <span class="numbers-font text-[10px] font-bold ${r.isReady ? 'text-emerald-400' : 'text-slate-400'}">
                        ${r.available.toLocaleString()} / ${r.quantityNeeded.toLocaleString()} ${r.isReady ? '✅' : ''}
                      </span>
                    </div>
                    ${!c.fulfilled ? `
                      <div class="w-full bg-slate-900 h-1.5 rounded-full overflow-hidden border border-slate-800">
                        <div class="h-full rounded-full transition-all duration-300 ${r.isReady ? 'bg-emerald-500' : 'bg-purple-500'}" style="width: ${r.pct}%"></div>
                      </div>
                    ` : ''}
                  </div>
                `).join('')}
              </div>

              ${c.fulfilled ? `
                <div class="text-[10px] text-emerald-400 font-bold flex items-center gap-1 pt-1 border-t border-slate-800/80">
                  <i class="fa-solid fa-circle-check"></i> تم تسليم كامل الشحنة المطلوبة للمستودعات.
                </div>
              ` : ''}
            </div>

            <div class="flex items-center justify-between p-2.5 bg-purple-950/30 rounded-xl border border-purple-500/20 text-xs relative z-10">
              <div>
                <span class="text-[10px] text-purple-300 block">المكافأة المالية والبونص</span>
                <span class="numbers-font font-black text-amber-400">${c.payout.toLocaleString()} EGP</span>
                <span class="text-[9px] text-emerald-400 font-bold mr-1">(+${c.bonusPercent}%)</span>
              </div>
              <div class="text-left">
                <span class="text-[10px] text-purple-300 block">سمعة المزرعة</span>
                <span class="numbers-font font-bold text-white">+${c.repReward} XP</span>
              </div>
            </div>

            <div class="relative z-10">
              ${c.fulfilled ? `
                <button disabled type="button"
                  class="w-full py-2.5 rounded-xl text-xs font-bold bg-emerald-500/10 text-emerald-400 border border-emerald-500/30 cursor-default flex items-center justify-center gap-2">
                  <i class="fa-solid fa-circle-check"></i>
                  <span>تم استلام الأرباح (${c.payout.toLocaleString()} EGP)</span>
                </button>
              ` : `
                <button ${(!canFulfillAll || exceedsDailyCap) ? 'disabled' : `onclick="window.UI?.fulfillFarmContract('${c.id}')"`} type="button"
                  class="w-full py-2.5 rounded-xl text-xs font-black transition flex items-center justify-center gap-2 ${canFulfillAll && !exceedsDailyCap ? 'bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-slate-950 shadow-lg shadow-emerald-500/20 active:scale-95 cursor-pointer' : 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'}">
                  <i class="${exceedsDailyCap ? 'fa-solid fa-ban text-rose-400' : 'fa-solid fa-truck-fast text-sm'}"></i>
                  <span>${exceedsDailyCap ? `تجاوز السقف اليومي (المتبقي: ${dailyLiq.remaining.toLocaleString()} EGP)` : (canFulfillAll ? 'تسليم الشحنة وتحصيل ' + c.payout.toLocaleString() + ' EGP 🚚' : (missingCount > 1 ? `المخزون ناقص (${missingCount} أصناف)` : 'المخزون غير كافٍ'))}</span>
                </button>
              `}
            </div>

          </div>
        `;
      });
      contractsGrid.innerHTML = cHtml;
    }
  }

  // ── FARM 2.0 USER ACTIONS & HANDLERS ──
  function plantAllPlots(cropId) {
    if (!cropId) {
      const cropSelect = document.getElementById('farm-quick-crop-select');
      cropId = cropSelect ? cropSelect.value : 'wheat';
    }
    try {
      const plantFn = (GameEngine && (GameEngine.plantAllPlots || GameEngine.plantAllFarmPlots));
      if (!plantFn) throw new Error("دالة زرع كل الأحواض غير متوفرة.");
      const res = plantFn.call(GameEngine, cropId);
      playMenuSound('click');
      showToast('غرس شامل 🌱', `تم غرس ${res.plantedCount} حوض بنجاح بمحصول "${res.crop.name}"!`, 'success');
      renderFarmPanel();
      renderStatsBar();
    } catch (e) {
      playMenuSound('error');
      showToast('تعذر الزراعة', e.message, 'error');
    }
  }

  function harvestAllPlots() {
    try {
      const harvestFn = (GameEngine && (GameEngine.harvestAllFarmPlots || GameEngine.harvestAllPlots));
      if (!harvestFn) throw new Error("دالة الحصاد الشامل غير متوفرة.");
      const res = harvestFn.call(GameEngine);
      playMenuSound('success');
      const count = res.harvestedCount || res.totalHarvestedPlots || 0;
      const yieldAmt = res.totalYield || 0;
      showToast('حصاد شامل 🌾', `تم حصد ${count} حوض بنجاح! تم تخزين ${yieldAmt.toLocaleString()} وحدة بالمستودع.`, 'success');
      renderFarmPanel();
      renderStatsBar();
    } catch (e) {
      playMenuSound('error');
      showToast('تعذر الحصاد', e.message, 'error');
    }
  }

