  // ─────────────────────────────────────────────
  //  TOP-UP & SUPPORT STORE CONTROLLER (متجر الشحن والدعم)
  // ─────────────────────────────────────────────
  let _activeSelectedTopupPkg = null;
  let _topupModalEventsBound = false;
  let _currentTopupPaymentSettings = null;
  let _cachedTopupPackagesList = [];
  let _activeTopupCategoryFilter = 'all';

  async function openTopupModal() {
    playMenuSound('modal_open');
    bindTopupModalEvents();

    const modal = document.getElementById('topup-store-modal');
    if (!modal) return;

    // Update real-time balance in modal
    const s = (typeof GameEngine !== 'undefined' && GameEngine.state) ? GameEngine.state : {};
    const pGoldEl = document.getElementById('topup-modal-player-gold');
    const pCashEl = document.getElementById('topup-modal-player-cash');
    if (pGoldEl) pGoldEl.textContent = Math.max(0, Number(s.gold || 0)).toLocaleString();
    if (pCashEl) pCashEl.textContent = formatCompactNumber(Math.max(0, Number(s.cash || 0)));

    // Reset views
    document.getElementById('topup-view-packages')?.classList.remove('hidden');
    document.getElementById('topup-view-confirmation')?.classList.add('hidden');
    document.getElementById('topup-success-notice')?.classList.add('hidden');
    document.getElementById('player-topup-form')?.classList.remove('hidden');

    modal.classList.remove('hidden');

    const container = document.getElementById('topup-packages-container');
    if (container) {
      container.innerHTML = '<div class="col-span-full p-8 text-center text-slate-400"><i class="fa-solid fa-spinner animate-spin text-xl text-amber-400 block mb-2"></i><span>جاري جلب باقات الشحن المعتمدة...</span></div>';
    }

    try {
      const [packages, settings] = await Promise.all([
        AppDB.getTopupPackages(),
        AppDB.getPaymentSettings()
      ]);

      _currentTopupPaymentSettings = settings;
      _cachedTopupPackagesList = packages || [];

      // Populate Payment Info in view 2
      const vodafoneNumEl = document.getElementById('player-topup-vodafone-num');
      const instapayNumEl = document.getElementById('player-topup-instapay-num');
      const instructionsEl = document.getElementById('player-topup-instructions');

      if (vodafoneNumEl) vodafoneNumEl.textContent = settings.vodafoneCash || 'غير محدد حالياً';
      if (instapayNumEl) instapayNumEl.textContent = settings.instapay || 'غير محدد حالياً';
      if (instructionsEl) instructionsEl.textContent = settings.notes || 'يرجى تحويل المبلغ بدقة وكتابة رقم الهاتف المحوّل منه ورقم العملية أو الوصل لتأكيد الشحن فوراً.';

      // Render packages
      renderTopupPackagesList(_cachedTopupPackagesList);
    } catch (err) {
      if (container) {
        container.innerHTML = `<div class="col-span-full p-4 text-center text-rose-400 bg-rose-950/40 rounded-2xl border border-rose-500/30">تعذر جلب باقات الشحن: ${err.message}</div>`;
      }
    }
  }

  function closeTopupModal() {
    const modal = document.getElementById('topup-store-modal');
    if (modal) modal.classList.add('hidden');
    _activeSelectedTopupPkg = null;
  }

  function getTopupPackageCategory(pkg) {
    if (pkg.category === 'cosmetics' || (pkg.features && (pkg.features.chatGlow || pkg.features.verified || pkg.features.customAvatar || pkg.features.stickersPack)) || (pkg.id && (pkg.id.includes('glow') || pkg.id.includes('flame') || pkg.id.includes('verified')))) {
      return 'cosmetics';
    }
    if (pkg.category === 'gold' || (pkg.gold && Number(pkg.gold) > 0) || (pkg.id && pkg.id.startsWith('gold_pack_'))) {
      return 'gold';
    }
    return 'cash';
  }

  function renderTopupPackagesList(packages) {
    const container = document.getElementById('topup-packages-container');
    if (!container) return;

    // Filter out packages hidden by admin
    let visiblePackages = (packages || []).filter(pkg => pkg.hidden !== true && pkg.visible !== false && pkg.active !== false);

    // Apply category filter
    if (_activeTopupCategoryFilter !== 'all') {
      visiblePackages = visiblePackages.filter(pkg => getTopupPackageCategory(pkg) === _activeTopupCategoryFilter);
    }

    if (visiblePackages.length === 0) {
      container.innerHTML = '<div class="col-span-full p-8 text-center text-slate-400 bg-slate-900/40 rounded-3xl border border-slate-800"><i class="fa-solid fa-box-open text-2xl text-slate-600 block mb-2"></i><span>لا توجد باقات متاحة في هذا التصنيف حالياً.</span></div>';
      return;
    }

    container.innerHTML = '';
    visiblePackages.forEach(pkg => {
      const card = document.createElement('div');
      const cat = getTopupPackageCategory(pkg);
      const isGoldPkg = cat === 'gold';
      const isCosmeticsPkg = cat === 'cosmetics';
      const isCashPkg = cat === 'cash';

      const goldAmt = Number(pkg.gold || 0);
      const speedupHours = Math.floor((goldAmt * 10) / 60);

      const badge = pkg.customBadge || '';
      const itemsList = pkg.items ? Object.entries(pkg.items).map(([k, v]) => {
        let label = k;
        if (k === 'vip_casino_pass') label = 'تصريح كازينو VIP';
        else if (k === 'swiss_safe') label = 'خزنة سويسرية';
        else if (k === 'offshore_account') label = 'حساب خارجي';
        else if (k === 'lottery_ticket') label = 'تذكرة يانصيب';
        else if (k === 'legalShield') label = 'درع قانوني';
        else if (k === 'safe_lock') label = 'أقفال أمان';
        return `${v}x ${label}`;
      }).join(' • ') : '';

      // High-end styling based on category
      let cardBorder = 'border-emerald-500/40 hover:border-emerald-300 hover:shadow-emerald-500/20';
      let cardBg = 'bg-gradient-to-b from-emerald-950/20 via-slate-900/95 to-slate-950';
      let glowBg = 'bg-emerald-500/10';
      let iconHtml = '💵';
      let iconBoxBg = 'bg-gradient-to-br from-emerald-400 to-teal-600 text-slate-950';

      if (isGoldPkg) {
        cardBorder = 'border-amber-500/40 hover:border-amber-300 hover:shadow-amber-500/20';
        cardBg = 'bg-gradient-to-b from-amber-950/25 via-slate-900/95 to-slate-950';
        glowBg = 'bg-amber-500/10';
        iconHtml = '🪙';
        iconBoxBg = 'bg-gradient-to-br from-amber-400 to-yellow-600 text-slate-950';
      } else if (isCosmeticsPkg) {
        cardBorder = 'border-purple-500/40 hover:border-purple-300 hover:shadow-purple-500/20';
        cardBg = 'bg-gradient-to-b from-purple-950/25 via-slate-900/95 to-slate-950';
        glowBg = 'bg-purple-500/10';
        iconHtml = badge ? formatCustomBadgeHtml(badge, 'text-xl') : '🎨';
        iconBoxBg = 'bg-gradient-to-br from-purple-400 to-pink-600 text-white';
      }

      card.className = `topup-pkg-card p-4 rounded-3xl ${cardBg} border-2 ${cardBorder} flex flex-col justify-between space-y-3.5 transition-all duration-300 shadow-xl relative overflow-hidden group`;

      // Header Tag/Pill
      let topPill = '';
      if (isGoldPkg) {
        if (goldAmt >= 800) topPill = '<span class="text-[9px] px-2 py-0.5 rounded-full bg-rose-500/20 border border-rose-500/40 text-rose-300 font-black">🔥 عرش الأباطرة</span>';
        else if (goldAmt >= 300) topPill = '<span class="text-[9px] px-2 py-0.5 rounded-full bg-amber-500/20 border border-amber-500/40 text-amber-300 font-black">⭐ الأكثر طلباً</span>';
        else topPill = '<span class="text-[9px] px-2 py-0.5 rounded-full bg-yellow-500/15 border border-yellow-500/30 text-yellow-300 font-black">⚡ تسريع فوري</span>';
      } else if (isCosmeticsPkg) {
        topPill = `<span class="text-[9px] px-2 py-0.5 rounded-full bg-purple-500/20 border border-purple-500/40 text-purple-300 font-black">🎨 مظاهر وإطارات VIP</span>`;
      } else {
        topPill = `<span class="text-[9px] px-2 py-0.5 rounded-full bg-emerald-500/20 border border-emerald-500/40 text-emerald-300 font-black">💵 سيولة واستثمار</span>`;
      }

      card.innerHTML = `
        <!-- Card Top Glow Accent -->
        <div class="absolute -top-12 -right-12 w-28 h-28 ${glowBg} rounded-full blur-2xl pointer-events-none group-hover:scale-150 transition-transform duration-500"></div>

        <!-- Card Content -->
        <div class="space-y-3 relative z-10">
          
          <!-- Top Row: Category Tag & Price -->
          <div class="flex items-center justify-between gap-2">
            <div>${topPill}</div>
            <div class="numbers-font text-amber-300 font-black text-xs sm:text-sm px-2.5 py-1 rounded-xl bg-gradient-to-r from-amber-500/20 to-yellow-500/10 border border-amber-500/40 shadow-inner flex items-center gap-1 font-mono">
              <span>${Number(pkg.price).toLocaleString()}</span>
              <span class="text-[10px] font-sans">EGP</span>
            </div>
          </div>

          <!-- Title & Icon -->
          <div class="flex items-center gap-2.5 pb-2 border-b border-slate-800/80">
            <div class="w-10 h-10 rounded-2xl ${iconBoxBg} flex items-center justify-center text-lg font-black shrink-0 shadow-md group-hover:rotate-6 transition-transform">
              ${iconHtml}
            </div>
            <div class="min-w-0">
              <h3 class="font-black text-white text-xs sm:text-sm truncate group-hover:text-amber-300 transition-colors">${pkg.name}</h3>
              <p class="text-[10px] text-slate-400 truncate mt-0.5">${(pkg.description || 'باقة مميزة لدعم السيرفر واكتساب موارد حصرية.')}</p>
            </div>
          </div>

          <!-- Highlight Rewards Box -->
          <div class="p-3 bg-slate-950/90 rounded-2xl border border-slate-850 space-y-2 text-[11px]">
            ${isGoldPkg ? `
              <div class="flex items-center justify-between p-2 rounded-xl bg-gradient-to-r from-amber-500/15 via-yellow-500/10 to-transparent border border-amber-500/30">
                <div class="flex items-center gap-1.5 font-black text-amber-300">
                  <span class="text-sm">🪙</span>
                  <span>رصيد الذهب:</span>
                </div>
                <span class="numbers-font font-black text-amber-400 text-sm font-mono">+${goldAmt.toLocaleString()} ذهبة</span>
              </div>
              <div class="text-[10px] text-slate-300 flex items-center gap-1.5 px-1">
                <i class="fa-solid fa-bolt-lightning text-amber-400"></i>
                <span>تعادل تسريع <strong>${speedupHours > 0 ? speedupHours + ' ساعة' : (goldAmt * 10) + ' دقيقة'}</strong> عمل/تهريب/سجن</span>
              </div>
            ` : ''}

            ${pkg.cash ? `
              <div class="flex justify-between items-center text-emerald-400 font-black">
                <span class="flex items-center gap-1.5"><i class="fa-solid fa-money-bill-wave text-xs"></i> كاش فوري:</span>
                <span class="numbers-font font-mono text-xs text-emerald-300 font-black">+${Number(pkg.cash).toLocaleString()} EGP</span>
              </div>
            ` : ''}

            ${pkg.bank ? `
              <div class="flex justify-between items-center text-sky-400 font-bold">
                <span class="flex items-center gap-1.5"><i class="fa-solid fa-building-columns text-xs"></i> وديعة بالبنك:</span>
                <span class="numbers-font font-mono text-xs text-sky-300">+${Number(pkg.bank).toLocaleString()} EGP</span>
              </div>
            ` : ''}

            ${pkg.features?.verified ? `
              <div class="flex justify-between items-center text-sky-300 font-bold">
                <span class="flex items-center gap-1.5"><i class="fa-solid fa-circle-check text-sky-400 text-xs"></i> شارة التوثيق:</span>
                <span class="badge-verified-glow inline-flex items-center gap-1 text-[10px]">
                  ${getVerifiedBadgeIconHtml('w-3.5 h-3.5')}
                  <span>موثق رسمي</span>
                </span>
              </div>
            ` : ''}

            ${pkg.features?.customAvatar ? `
              <div class="flex justify-between items-center text-pink-400 font-bold">
                <span class="flex items-center gap-1.5"><i class="fa-solid fa-image text-xs"></i> ميزة الصورة الشخصية:</span>
                <span class="px-2 py-0.5 bg-pink-500/20 text-pink-300 border border-pink-500/30 rounded text-[10px] font-bold">رفع صورة مخصصة</span>
              </div>
            ` : ''}

            ${badge ? `
              <div class="flex justify-between items-center text-yellow-400 font-bold p-1.5 rounded-xl bg-slate-900/80 border border-slate-800">
                <span class="flex items-center gap-1.5"><i class="fa-solid fa-crown text-amber-400 text-xs"></i> وسام VIP:</span>
                <span class="flex items-center gap-1.5">${formatCustomBadgeHtml(badge, 'text-sm')}</span>
              </div>
            ` : ''}

            ${pkg.features?.chatGlow ? `
              <div class="mt-2 p-2.5 rounded-2xl bg-slate-900/90 border border-purple-500/40 space-y-1.5 shadow-inner">
                <div class="flex items-center justify-between text-[10px] text-purple-300 font-black border-b border-slate-800 pb-1">
                  <span class="flex items-center gap-1.5"><i class="fa-solid fa-wand-magic-sparkles text-purple-400"></i> معاينة إطار ورسالة الشات:</span>
                  <span class="text-[9px] px-1.5 py-0.2 bg-purple-500/20 rounded font-mono text-purple-200">
                    ${pkg.features.chatGlow === 'blue_flame' ? '⚡ لهيب أزرق' : (pkg.features.chatGlow === 'crimson_flame' ? '🔥 لهيب قرمزي' : (pkg.features.chatGlow === 'cyber_rainbow' ? '🌈 سايبر ملكي' : '✨ نيون ذهبي'))}
                  </span>
                </div>
                <div class="chat-message-bubble ${pkg.features.chatGlow === 'blue_flame' ? 'chat-bubble-glow-blue-flame' : (pkg.features.chatGlow === 'crimson_flame' ? 'chat-bubble-glow-flame' : (pkg.features.chatGlow === 'cyber_rainbow' ? 'chat-bubble-glow-rainbow' : 'chat-bubble-glow-gold'))} p-2 rounded-xl text-right text-[11px]">
                  <div class="flex items-center gap-1.5 mb-0.5 justify-start">
                    <span class="text-[10px] font-black ${pkg.features.chatGlow === 'blue_flame' ? 'chat-sender-blue-flame-glow' : (pkg.features.chatGlow === 'crimson_flame' ? 'chat-sender-flame-glow' : (pkg.features.chatGlow === 'cyber_rainbow' ? 'chat-sender-rainbow-glow' : 'chat-sender-gold-glow'))}">اسمك</span>
                    ${badge ? formatCustomBadgeHtml(badge, 'text-[9px]') : ''}
                  </div>
                  <div class="text-white text-[10.5px] font-medium leading-tight">
                    ${pkg.features.chatGlow === 'blue_flame' ? 'رسالة مميزة بإطار اللهب الأزرق الملكي ⚡' : (pkg.features.chatGlow === 'crimson_flame' ? 'رسالة مشتعلة باللهب القرمزي الملكي! 🔥' : (pkg.features.chatGlow === 'cyber_rainbow' ? 'حضور أسطوري متوهج بألوان السايبر 👑' : 'رسالة ذهبية متوهجة في الشات العام ✨'))}
                  </div>
                </div>
              </div>
            ` : ''}

            ${pkg.xp ? `
              <div class="flex justify-between items-center text-cyan-400 font-bold">
                <span class="flex items-center gap-1.5"><i class="fa-solid fa-star text-xs"></i> نقاط خبرة:</span>
                <span class="numbers-font font-mono text-xs text-cyan-300">+${Number(pkg.xp).toLocaleString()} XP</span>
              </div>
            ` : ''}

            ${itemsList ? `
              <div class="flex justify-between items-center text-purple-300 font-bold pt-1 border-t border-slate-850">
                <span class="flex items-center gap-1.5"><i class="fa-solid fa-box text-xs"></i> معدات إضافية:</span>
                <span class="text-[10px] text-purple-200 truncate max-w-[130px]">${itemsList}</span>
              </div>
            ` : ''}
          </div>
        </div>

        <!-- Action Button -->
        <button class="btn-select-topup-pkg w-full py-2.5 bg-gradient-to-r from-amber-500 via-yellow-400 to-amber-500 hover:from-amber-400 hover:to-yellow-300 text-slate-950 font-black rounded-2xl text-xs transition-all duration-200 flex items-center justify-center gap-2 shadow-lg shadow-amber-500/25 active:scale-95 cursor-pointer relative z-10 group-hover:shadow-amber-500/40">
          <i class="fa-solid fa-bolt text-slate-950"></i>
          <span>طلب وشحن الباقة الآن</span>
        </button>`;

      card.querySelector('.btn-select-topup-pkg').onclick = () => {
        selectPackageForTopup(pkg);
      };

      container.appendChild(card);
    });
  }

  function selectPackageForTopup(pkg) {
    playMenuSound('click');
    _activeSelectedTopupPkg = pkg;

    const summaryEl = document.getElementById('topup-selected-pkg-summary');
    if (summaryEl) {
      const badge = pkg.customBadge ||'';
      summaryEl.innerHTML =`
        <div class="flex items-center gap-2.5 min-w-0">
          ${badge ?`<span class="text-2xl shrink-0 inline-flex items-center justify-center">${formatCustomBadgeHtml(badge, 'text-2xl')}</span>` :''}
          <div class="min-w-0">
            <h4 class="font-black text-white text-xs sm:text-sm truncate">${pkg.name}</h4>
            <span class="text-[10px] text-amber-300 block">المبلغ المطلوب تحويله: <strong class="numbers-font text-amber-400 font-black text-xs">${Number(pkg.price).toLocaleString()} EGP</strong></span>
          </div>
        </div>
        <span class="text-[10px] px-2.5 py-1 bg-amber-500/20 text-amber-300 rounded-xl border border-amber-500/30 font-black shrink-0">باقة مختارة</span>`;
    }

    // Reset inputs & notice
    const phoneInput = document.getElementById('topup-sender-phone');
    const receiptInput = document.getElementById('topup-receipt-number');
    if (phoneInput) phoneInput.value ='';
    if (receiptInput) receiptInput.value ='';

    document.getElementById('topup-success-notice')?.classList.add('hidden');
    document.getElementById('player-topup-form')?.classList.remove('hidden');

    document.getElementById('topup-view-packages')?.classList.add('hidden');
    document.getElementById('topup-view-confirmation')?.classList.remove('hidden');
  }

  async function submitTopupOrder() {
    if (!_activeSelectedTopupPkg) {
      showToast('خطأ','يرجى اختيار باقة شحن أولاً.','error');
      return;
    }

    const phone = (document.getElementById('topup-sender-phone')?.value ||'').trim();
    const receipt = (document.getElementById('topup-receipt-number')?.value ||'').trim();
    const submitBtn = document.getElementById('btn-submit-topup-request');
    const btnText = document.getElementById('topup-submit-btn-text');

    if (!phone || !receipt) {
      showToast('بيانات ناقصة','يرجى إدخال رقم الهاتف المحوّل منه ورقم العملية أو الوصل.','error');
      return;
    }

    try {
      if (submitBtn) submitBtn.disabled = true;
      if (btnText) btnText.innerHTML ='<i class="fa-solid fa-spinner animate-spin"></i> جاري الإرسال...';

      const requestPayload = {
        username: GameEngine.activeUsername,
        packageId: _activeSelectedTopupPkg.id,
        packageName: _activeSelectedTopupPkg.name,
        price: _activeSelectedTopupPkg.price,
        rewards: {
          cash: _activeSelectedTopupPkg.cash || 0,
          bank: _activeSelectedTopupPkg.bank || 0,
          gold: _activeSelectedTopupPkg.gold || 0,
          xp: _activeSelectedTopupPkg.xp || 0,
          customBadge: _activeSelectedTopupPkg.customBadge ||'',
          badgeTitle: _activeSelectedTopupPkg.badgeTitle ||'',
          items: _activeSelectedTopupPkg.items || {}
        },
        senderPhoneOrName: phone,
        receiptNumber: receipt
      };

      await AppDB.submitTopupRequest(requestPayload);

      playCasinoSound('win');
      showToast('تم الإرسال بنجاح','طلب الشحن قيد المراجعة لدى الإدارة حالياً.','success');

      document.getElementById('player-topup-form')?.classList.add('hidden');
      document.getElementById('topup-success-notice')?.classList.remove('hidden');
    } catch (err) {
      showToast('خطأ في إرسال الطلب', err.message ||'تعذر إرسال الطلب','error');
    } finally {
      if (submitBtn) submitBtn.disabled = false;
      if (btnText) btnText.textContent ='إرسال طلب الشحن للإدارة';
    }
  }

  function bindTopupModalEvents() {
    if (_topupModalEventsBound) return;
    _topupModalEventsBound = true;

    // Filter tab buttons
    const filterTabs = document.querySelectorAll('.topup-filter-tab');
    filterTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        playMenuSound('click');
        const cat = tab.dataset.category || 'all';
        _activeTopupCategoryFilter = cat;

        filterTabs.forEach(t => {
          t.classList.remove('bg-gradient-to-r', 'from-amber-500', 'to-yellow-500', 'text-slate-950', 'shadow-md', 'shadow-amber-500/20');
          t.classList.add('bg-slate-900/90', 'text-slate-300', 'border', 'border-slate-800');
        });

        tab.classList.add('bg-gradient-to-r', 'from-amber-500', 'to-yellow-500', 'text-slate-950', 'shadow-md', 'shadow-amber-500/20');
        tab.classList.remove('bg-slate-900/90', 'text-slate-300', 'border', 'border-slate-800');

        renderTopupPackagesList(_cachedTopupPackagesList);
      });
    });

    // Close button
    const closeBtn = document.getElementById('btn-close-topup-modal');
    if (closeBtn) closeBtn.onclick = () => closeTopupModal();

    // Back to packages button
    const backBtn = document.getElementById('btn-topup-back-to-pkgs');
    if (backBtn) {
      backBtn.onclick = () => {
        playMenuSound('click');
        document.getElementById('topup-view-packages')?.classList.remove('hidden');
        document.getElementById('topup-view-confirmation')?.classList.add('hidden');
      };
    }

    // Copy Vodafone Cash
    const copyVodafoneBtn = document.getElementById('btn-copy-topup-vodafone');
    if (copyVodafoneBtn) {
      copyVodafoneBtn.onclick = () => {
        const num = document.getElementById('player-topup-vodafone-num')?.textContent ||'';
        navigator.clipboard.writeText(num.trim());
        showToast('تم النسخ','تم نسخ رقم فودافون كاش للحافظة.','info');
      };
    }

    // Copy InstaPay
    const copyInstapayBtn = document.getElementById('btn-copy-topup-instapay');
    if (copyInstapayBtn) {
      copyInstapayBtn.onclick = () => {
        const num = document.getElementById('player-topup-instapay-num')?.textContent ||'';
        navigator.clipboard.writeText(num.trim());
        showToast('تم النسخ','تم نسخ حساب انستاباي للحافظة.','info');
      };
    }

    // Copy PayPal
    const copyPaypalBtn = document.getElementById('btn-copy-topup-paypal');
    if (copyPaypalBtn) {
      copyPaypalBtn.onclick = () => {
        const num = document.getElementById('player-topup-paypal-num')?.textContent ||'';
        navigator.clipboard.writeText(num.trim());
        showToast('تم النسخ','تم نسخ رابط PayPal للحافظة.','info');
      };
    }
  }
  // ─────────────────────────────────────────────
  //  NOTIFICATIONS & MESSAGES CENTER CONTROLLER
  // ─────────────────────────────────────────────
  let _notificationsModalEventsBound = false;

  function bindNotificationsModalEvents() {
    if (_notificationsModalEventsBound) return;
    _notificationsModalEventsBound = true;

    // Filter tabs
    const filterBtns = document.querySelectorAll('.mailbox-tab-btn');
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        playMenuSound('click');
        filterBtns.forEach(b => {
          b.classList.remove('active','bg-amber-500','text-slate-950','font-black');
          b.classList.add('bg-slate-900','text-slate-300','font-bold');
        });
        btn.classList.add('active','bg-amber-500','text-slate-950','font-black');
        btn.classList.remove('bg-slate-900','text-slate-300','font-bold');

        _currentMailboxFilter = btn.dataset.filter ||'all';
        if (window.lastMailsCache) {
          renderMailbox(window.lastMailsCache);
        }
      });
    });

    // Close button
    const closeBtn = document.getElementById('btn-close-notifications-modal');
    if (closeBtn) closeBtn.addEventListener('click', closeNotificationsModal);

    // Mark all read button
    const markAllBtn = document.getElementById('btn-mark-all-mails-read');
    if (markAllBtn) markAllBtn.addEventListener('click', markAllMailsReadAction);
  }

  async function openNotificationsModal() {
    playMenuSound('modal_open');
    bindNotificationsModalEvents();
    const modal = document.getElementById('modal-notifications-center');
    if (modal) modal.classList.remove('hidden');
    
    if (window.lastMailsCache && window.lastMailsCache.length > 0) {
      renderMailbox(window.lastMailsCache);
    }

    const myUser = (typeof GameEngine !== 'undefined' && GameEngine.activeUsername) || 
                   (typeof GameEngine !== 'undefined' && GameEngine.state && GameEngine.state.username) || 
                   localStorage.getItem('rasalmal_active_session_user');
    if (myUser && typeof AppDB !== 'undefined' && typeof AppDB.getMailbox === 'function') {
      try {
        const mails = await AppDB.getMailbox(myUser);
        if (mails && Array.isArray(mails)) {
          renderMailbox(mails);
        }
      } catch (_) {}
    }
  }

  function closeNotificationsModal() {
    playMenuSound('modal_close');
    const modal = document.getElementById('modal-notifications-center');
    if (modal) modal.classList.add('hidden');
  }

  async function markAllMailsReadAction() {
    if (!GameEngine.activeUsername) return;
    try {
      playMenuSound('click');
      await AppDB.markAllMailsRead(GameEngine.activeUsername);
      showToast('صندوق البريد','تم تحديد كافة الرسائل والإشعارات كمقروءة','success');
      if (window.lastMailsCache) {
        window.lastMailsCache.forEach(m => {
          if (m.status ==='unread' || m.status ==='pending') m.status ='read';
        });
        renderMailbox(window.lastMailsCache);
      }
    } catch (e) {
      showToast('خطأ','تعذر تحديث حالة الإشعارات','error');
    }
  }

