// Global watchdog for mandatory reload (Instant trigger every 3s when active)
if (typeof window !== 'undefined' && !window._IS_ADMIN_PAGE && !document.querySelector('#admin-container, #admin-auth-screen, #admin-main-interface')) {
    let _lastVersionCheckWatchdog = 0;
  const checkForceReloadWatchdog = async () => {
    if (typeof AppDB !=='undefined' && typeof AppDB.isNetworkActive ==='function' && !AppDB.isNetworkActive()) return;
    if (typeof document !=='undefined' && document.hidden) return;
    try {
      // 1. Check Admin Force Reload broadcast
      if (typeof AppDB !=='undefined' && typeof AppDB.getForceReloadStatus ==='function') {
        const reloadData = await AppDB.getForceReloadStatus();
        if (reloadData && reloadData.timestamp) {
          if (window.UIController && typeof window.UIController.handleIncomingForceReload ==='function') {
            window.UIController.handleIncomingForceReload(reloadData);
          }
        }
      }

      // 2. Check Maintenance & Suspicion Mode status
      if (GameEngine.state) {
        const isSusp = Boolean(
          GameEngine.state.underSuspicion || 
          (GameEngine.state.state && GameEngine.state.state.underSuspicion) ||
          (GameEngine.state.freezeUntil && GameEngine.state.freezeUntil > Date.now()) ||
          (GameEngine.state.state && GameEngine.state.state.freezeUntil && GameEngine.state.state.freezeUntil > Date.now())
        );
        if (isSusp) {
          enforceSuspicionStatus(true);
        }
      }
      if (typeof checkMaintenanceMode === 'function') {
        await checkMaintenanceMode();
      }

      // 3. Ultra-fast Version & Build Enforcer Watchdog (Every 5 seconds)
      const now = Date.now();
      if (now - _lastVersionCheckWatchdog >= 5000) {
        _lastVersionCheckWatchdog = now;
        try {
          const res = await fetch('/version.json?_t=' + now, { cache: 'no-store' });
          if (res.ok) {
            const s = await res.json();
            const curVer = (window._CLIENT_VERSION || 'v9.4.8');
            if (s && s.version && s.version !== curVer) {
              const curParam = new URL(window.location.href).searchParams.get('_v');
              if (curParam === s.version) {
                return; // Already running with target version param
              }
              const loopKey = 'rasalmal_watchdog_reload_' + s.version;
              const reloadedCount = Number(sessionStorage.getItem(loopKey) || 0);
              if (reloadedCount < 1) {
                sessionStorage.setItem(loopKey, String(reloadedCount + 1));
                console.warn('[Auto-Updater] Game update detected:', s.version, 'Current:', curVer, 'Triggering instant auto-update.');
                
                // Flush local state cleanly before reloading to avoid any data loss
                try {
                  if (typeof GameEngine !== 'undefined' && GameEngine.activeUsername && typeof AppDB !== 'undefined' && typeof AppDB.flushStateToCloudOnExit === 'function') {
                    AppDB.flushStateToCloudOnExit(GameEngine.activeUsername, GameEngine.state);
                  }
                } catch (_) {}

                if ('caches' in window) {
                  try {
                    const keys = await caches.keys();
                    await Promise.all(keys.map(k => caches.delete(k)));
                  } catch (_) {}
                }
                if ('serviceWorker' in navigator) {
                  try {
                    const regs = await navigator.serviceWorker.getRegistrations();
                    await Promise.all(regs.map(r => r.unregister()));
                  } catch (_) {}
                }
                const url = new URL(window.location.href);
                url.searchParams.set('_v', s.version);
                window.location.replace(url.toString());
                return;
              }
            }
          }
        } catch (_) {}
      }
    } catch (e) {}
  };

  setInterval(checkForceReloadWatchdog, 5000);
  checkForceReloadWatchdog();


  if (typeof document !== 'undefined') {
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden) checkForceReloadWatchdog();
    });
  }
  if (typeof window !== 'undefined') {
    window.addEventListener('focus', checkForceReloadWatchdog);
  }

  // ── REALTIME NETWORK CONNECTION WATCHER ─────────────────────────────────
  function initNetworkWatcher() {
    const offlineOverlay = document.getElementById('offline-overlay');
    const retryBtn = document.getElementById('btn-retry-connect');
    const errDesc = document.getElementById('offline-error-description');

    let isCurrentlyOffline = (typeof navigator !== 'undefined' && navigator.onLine === false);

    async function checkServerPing() {
      try {
        const res = await fetch('/version.json?_ping=' + Date.now(), { method: 'HEAD', cache: 'no-store' });
        return res.ok;
      } catch (e) {
        return false;
      }
    }

    function showOfflineScreen(customMsg = null) {
      if (!offlineOverlay) return;
      isCurrentlyOffline = true;
      offlineOverlay.classList.remove('hidden');
      offlineOverlay.classList.add('flex');
      if (errDesc) {
        errDesc.textContent = customMsg || 'انقطع الاتصال بالإنترنت، يرجى إعادة تفعيل الشبكة للمتابعة...';
      }
      if (typeof GameEngine !== 'undefined' && typeof GameEngine.pauseEngine === 'function') {
        try { GameEngine.pauseEngine(); } catch (_) {}
      }
    }

    function hideOfflineScreen() {
      if (!offlineOverlay) return;
      isCurrentlyOffline = false;
      offlineOverlay.classList.add('hidden');
      offlineOverlay.classList.remove('flex');
      if (typeof GameEngine !== 'undefined' && typeof GameEngine.resumeEngine === 'function') {
        try { GameEngine.resumeEngine(); } catch (_) {}
      }
      showToast('🟢 متصل بالإنترنت', 'تمت استعادة الاتصال بالخوادم بنجاح ومزامنة البيانات.', 'success');
      if (typeof GameEngine !== 'undefined' && typeof GameEngine.forceSaveState === 'function') {
        try { GameEngine.forceSaveState(true); } catch (_) {}
      }
    }

    window.addEventListener('offline', () => {
      console.warn('[NetworkWatcher] Offline event detected.');
      showOfflineScreen();
    });

    window.addEventListener('online', async () => {
      console.log('[NetworkWatcher] Online event detected, verifying ping...');
      if (errDesc) errDesc.textContent = 'جاري التحقق من استقرار الاتصال بالخادم...';
      const ok = await checkServerPing();
      if (ok) {
        hideOfflineScreen();
      } else {
        showOfflineScreen('تعذر الوصول إلى الخادم رغم توفر اتصال محلي.');
      }
    });

    if (retryBtn) {
      retryBtn.addEventListener('click', async () => {
        retryBtn.disabled = true;
        const origHtml = retryBtn.innerHTML;
        retryBtn.innerHTML = '<i class="fa-solid fa-spinner animate-spin"></i> <span>جاري فحص الاتصال...</span>';
        if (errDesc) errDesc.textContent = 'جاري فحص الاتصال بالخادم...';
        
        const ok = await checkServerPing();
        if (ok) {
          hideOfflineScreen();
        } else {
          showToast('⚠️ لا يزال الاتصال منقطعاً', 'تأكد من تشغيل الواي فاي أو باقة البيانات ثم أعد المحاولة.', 'error');
          if (errDesc) errDesc.textContent = 'فشلت محاولة الاتصال، يرجى فحص الشبكة...';
        }
        retryBtn.disabled = false;
        retryBtn.innerHTML = origHtml;
      });
    }

    // Periodic background health-check every 4s to catch silent dropped connections
    setInterval(async () => {
      if (typeof navigator !== 'undefined') {
        if (!navigator.onLine && !isCurrentlyOffline) {
          showOfflineScreen();
        }
      }
    }, 4000);
  }

  initNetworkWatcher();
}

