  window._adminOnAuctionTypeChanged = function(type) {
    const goldBox = document.getElementById('adm-box-auc-gold-amount');
    const nameEl = document.getElementById('adm-input-auc-name');
    const iconEl = document.getElementById('adm-input-auc-icon');
    const badgeEl = document.getElementById('adm-input-auc-badge');
    const descEl = document.getElementById('adm-input-auc-desc');
    const goldAmountEl = document.getElementById('adm-input-auc-gold-amount');

    if (type === 'gold') {
      if (goldBox) {
        goldBox.classList.remove('opacity-40');
        goldBox.classList.add('ring-2', 'ring-amber-500/80', 'bg-amber-950/60');
      }
      if (nameEl && (!nameEl.value || nameEl.value.includes('إطار') || nameEl.value.includes('طائرة'))) {
        nameEl.value = 'احتياطي الذهب الملكي 🥇';
      }
      if (iconEl && (!iconEl.value || iconEl.value === '🔥' || iconEl.value === '✈️')) iconEl.value = '🥇';
      if (badgeEl && (!badgeEl.value || badgeEl.value.includes('إطار') || badgeEl.value.includes('أسطول'))) badgeEl.value = 'احتياطي ذهب ملكي';
      if (descEl && (!descEl.value || descEl.value.includes('إطار') || descEl.value.includes('طائرة'))) {
        descEl.value = 'سبائك ذهب نقي تمنحك سيولة فورية وقوة استثمارية كاسحة في البورصة والصفقات';
      }
    } else {
      if (goldBox) {
        goldBox.classList.remove('ring-2', 'ring-amber-500/80', 'bg-amber-950/60');
      }
    }
  };

  function parseSafeMoney(val, fallback = 0) {
    if (val === null || val === undefined) return fallback;
    if (typeof val === 'number') return isNaN(val) ? fallback : Math.max(0, Math.floor(val));
    let s = String(val).trim();
    if (!s) return fallback;
    // Convert Arabic-Indic numerals
    s = s.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
    s = s.replace(/،/g, ',');
    let mult = 1;
    if (/([kK]|الف|ألف)/i.test(s)) {
      mult = 1000;
      s = s.replace(/([kK]|الف|ألف)/gi, '');
    } else if (/([mM]|مليون)/i.test(s)) {
      mult = 1000000;
      s = s.replace(/([mM]|مليون)/gi, '');
    } else if (/([bB]|مليار)/i.test(s)) {
      mult = 1000000000;
      s = s.replace(/([bB]|مليار)/gi, '');
    }
    s = s.replace(/[^\d.-]/g, '');
    const n = parseFloat(s);
    if (isNaN(n)) return fallback;
    return Math.max(0, Math.floor(n * mult));
  }
  window._parseSafeMoney = parseSafeMoney;

  window._adminApplyAuctionPreset = function(presetKey) {
    const p = AUCTION_PRESETS[presetKey];
    if (!p) return;
    const nameEl = document.getElementById('adm-input-auc-name');
    const typeEl = document.getElementById('adm-input-auc-type');
    const iconEl = document.getElementById('adm-input-auc-icon');
    const badgeEl = document.getElementById('adm-input-auc-badge');
    const descEl = document.getElementById('adm-input-auc-desc');
    const startPriceEl = document.getElementById('adm-input-auc-start-price');
    const minStepEl = document.getElementById('adm-input-auc-min-step');
    const minNetWorthEl = document.getElementById('adm-input-auc-min-networth');
    const goldAmountEl = document.getElementById('adm-input-auc-gold-amount');

    if (nameEl) nameEl.value = p.name;
    if (typeEl) {
      typeEl.value = p.type;
      window._adminOnAuctionTypeChanged(p.type);
    }
    if (iconEl) iconEl.value = p.icon;
    if (badgeEl) badgeEl.value = p.badge;
    if (descEl) descEl.value = p.description;
    if (startPriceEl) startPriceEl.value = p.startPrice.toLocaleString();
    if (minStepEl) minStepEl.value = p.minStep.toLocaleString();
    if (minNetWorthEl) minNetWorthEl.value = p.minNetWorth.toLocaleString();
    if (goldAmountEl && p.rewardData && typeof p.rewardData.gold === 'number') {
      goldAmountEl.value = p.rewardData.gold;
    }

    if (typeof showToast === 'function') showToast('نموذج المزاد', `تم تطبيق إعدادات [${p.name}]`, 'info');
  };

  window._adminSubmitCreateAuction = async function() {
    const name = (document.getElementById('adm-input-auc-name')?.value || '').trim();
    const type = document.getElementById('adm-input-auc-type')?.value || 'chat_frame';
    const icon = (document.getElementById('adm-input-auc-icon')?.value || '🏆').trim();
    const badge = (document.getElementById('adm-input-auc-badge')?.value || 'مزاد رسمي').trim();
    const desc = (document.getElementById('adm-input-auc-desc')?.value || '').trim();
    const startPrice = parseSafeMoney(document.getElementById('adm-input-auc-start-price')?.value, 10000000);
    const minStep = Math.max(1000, parseSafeMoney(document.getElementById('adm-input-auc-min-step')?.value, 1000000));
    const minNetWorth = parseSafeMoney(document.getElementById('adm-input-auc-min-networth')?.value, 0);
    const delayMins = Math.max(1, parseSafeMoney(document.getElementById('adm-input-auc-delay-mins')?.value, 10));
    const goldAmount = Math.max(1, parseSafeMoney(document.getElementById('adm-input-auc-gold-amount')?.value, 1000));
    const museumQuantity = Math.max(1, parseSafeMoney(document.getElementById('adm-input-auc-museum-quantity')?.value, 1));

    if (!name) {
      if (typeof showToast === 'function') showToast('خطأ', 'اسم المعروض مطلوب.', 'warning');
      else alert('اسم المعروض مطلوب.');
      return;
    }

    let rewardData = {};
    if (type === 'chat_frame') rewardData.frameId = 'frame_custom_' + Date.now();
    if (type === 'gold') rewardData.gold = goldAmount;
    if (type === 'aircraft') rewardData.aircraftId = 'plane_custom_' + Date.now();
    if (type === 'museum_item') {
      rewardData.isMuseumRelic = true;
      rewardData.quantity = museumQuantity;
      if (window._selectedAuctionRelicData) {
        rewardData = { ...window._selectedAuctionRelicData, ...rewardData, quantity: museumQuantity };
      }
    }

    // Check if matching preset
    for (const key in AUCTION_PRESETS) {
      if (AUCTION_PRESETS[key].name === name || AUCTION_PRESETS[key].id === name) {
        rewardData = { ...AUCTION_PRESETS[key].rewardData };
      }
    }

    // Always enforce the explicit gold amount if type is gold or reward has gold
    if (type === 'gold' || rewardData.gold) {
      rewardData.gold = goldAmount;
    }
    if (type === 'museum_item') {
      rewardData.isMuseumRelic = true;
      rewardData.quantity = museumQuantity;
    }

    try {
      const res = await fetch(getAdminApiUrl('/api/auction/admin/create'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${getAdminApiMasterKey()}`
        },
        body: JSON.stringify({
          item: { type, name, description: desc, icon, badge, rewardData },
          config: { startingBid: startPrice, minBidStep: minStep, minNetWorth, hammerDurationSeconds: 60 },
          startDelayMinutes: delayMins
        })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'فشل جدولة المزاد.');

      if (typeof showToast === 'function') showToast('نجاح الجدولة', `تم إطلاق المزاد الملكي بنجاح! السعر: ${startPrice.toLocaleString()} ج.م | شرط الثروة: ${minNetWorth.toLocaleString()} ج.م`, 'success');
      else alert('تم إطلاق ونشر المزاد الملكي بنجاح!');

      if (typeof logAdminAction === 'function') logAdminAction(`جدولة مزاد ملكي جديد: ${name} (افتتاح: ${startPrice.toLocaleString()}، شرط: ${minNetWorth.toLocaleString()})`);
      window._adminRefreshAuctionTelemetry();
    } catch (e) {
      if (typeof showToast === 'function') showToast('خطأ', e.message, 'error');
      else alert(e.message);
    }
  };

  window._adminForceStartAuction = async function() {
    try {
      const res = await fetch(getAdminApiUrl('/api/auction/admin/start'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${getAdminApiMasterKey()}`
        },
        body: JSON.stringify({})
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'فشل بدء المزاد.');

      if (typeof showToast === 'function') showToast('بدء المزاد الحي', 'تم فتح قاعة المزاد للمزايدات الحية الآن!', 'success');
      if (typeof logAdminAction === 'function') logAdminAction('بدء البث الحي للمزاد الملكي فورياً');
      window._adminRefreshAuctionTelemetry();
    } catch (e) {
      if (typeof showToast === 'function') showToast('خطأ', e.message, 'error');
      else alert(e.message);
    }
  };

  window._adminExecuteHammer = async function(action) {
    try {
      const res = await fetch(getAdminApiUrl('/api/auction/admin/hammer'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${getAdminApiMasterKey()}`
        },
        body: JSON.stringify({ action })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'فشل تنفيذ ضربة المطرقة.');

      if (typeof showToast === 'function') showToast('المطرقة الإدارية 🔨', data.message || 'تم تنفيذ الضربة بنجاح', 'success');
      if (typeof logAdminAction === 'function') logAdminAction(`تنفيذ إجراء المطرقة: ${action}`);
      window._adminRefreshAuctionTelemetry();
    } catch (e) {
      if (typeof showToast === 'function') showToast('خطأ', e.message, 'error');
      else alert(e.message);
    }
  };

  window._adminRefreshAuctionTelemetry = async function() {
    try {
      const res = await fetch(getAdminApiUrl('/api/auction/state?username=admin'), {
        headers: { 'Cache-Control': 'no-cache' }
      });
      if (!res.ok) return;
      const data = await res.json();

      const pill = document.getElementById('adm-auc-status-pill');
      const timer = document.getElementById('adm-auc-live-timer');
      const icon = document.getElementById('adm-auc-item-icon');
      const name = document.getElementById('adm-auc-item-name');
      const desc = document.getElementById('adm-auc-item-desc');
      const bid = document.getElementById('adm-auc-current-bid');
      const bidder = document.getElementById('adm-auc-highest-bidder');
      const regCount = document.getElementById('adm-auc-registrants-count');
      const minNw = document.getElementById('adm-auc-min-networth-display');
      const hammerMsg = document.getElementById('adm-auc-hammer-msg');
      const strikeBadge = document.getElementById('adm-auc-strike-badge');

      if (pill) {
        pill.textContent = data.status === 'LIVE' ? '🔴 بث حي مباشر' : (data.status === 'SCHEDULED' ? '⏳ مجدول وتنازلي' : (data.status === 'ENDED' ? '👑 تم البيع' : 'خامل'));
        pill.className = `px-2 py-0.5 rounded-full text-[10px] font-black ${data.status === 'LIVE' ? 'bg-rose-500/20 text-rose-400 border border-rose-500/40' : 'bg-amber-500/20 text-amber-300 border border-amber-500/30'}`;
      }

      if (data.item) {
        if (icon) icon.textContent = data.item.icon || '🏆';
        if (name) name.textContent = data.item.name || 'غرض ملكي';
        if (desc) desc.textContent = data.item.description || '--';
      }

      if (bid) bid.textContent = `${Number(data.live?.currentBid || 0).toLocaleString()} EGP`;
      if (bidder) bidder.textContent = data.live?.highestBidder ? data.live.highestBidder.username : 'لا يوجد مزايد بعد';
      if (regCount) regCount.textContent = `${data.registrantsCount || 0} لاعب`;
      if (minNw) minNw.textContent = `${Number(data.config?.minNetWorth || 0).toLocaleString()} EGP`;

      if (hammerMsg) {
        hammerMsg.innerHTML = `<i class="fa-solid fa-gavel text-amber-400"></i> <span>${data.live?.hammerStrikeMessage || 'جاهز لتلقي أوامر المطرقة...'}</span>`;
      }
      if (strikeBadge) {
        strikeBadge.textContent = `الضربة ${data.live?.hammerStrike || 0} / 3`;
      }

      if (timer) {
        const target = data.status === 'LIVE' ? data.live?.hammerExpiryTime : data.config?.scheduledStartTime;
        if (target) {
          const diff = Math.max(0, target - Date.now());
          const m = Math.floor(diff / 60000);
          const s = Math.floor((diff % 60000) / 1000);
          timer.textContent = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
        } else {
          timer.textContent = '--:--';
        }
      }
    } catch (e) {}
  };

  setInterval(() => {
    const p = document.getElementById('admin-subpanel-auctions');
    if (p && !p.classList.contains('hidden')) {
      if (typeof window._adminRefreshAuctionTelemetry === 'function') {
        window._adminRefreshAuctionTelemetry();
      }
    }
  }, 2000);

  // ==========================================
  // ROYAL MUSEUM ADMIN VAULT & RELIC MINTING
  // ==========================================
  window._adminRefreshMuseumCatalog = async function() {
    const tbody = document.getElementById('adm-museum-items-tbody');
    if (!tbody) return;

    try {
      const res = await fetch(getAdminApiUrl('/api/museum/items'), {
        headers: { 'Cache-Control': 'no-cache' }
      });
      if (!res.ok) return;
      const data = await res.json();
      const items = data.items || [];

      if (items.length === 0) {
        tbody.innerHTML = '<tr><td colspan="5" class="p-4 text-center text-slate-500">لا توجد تحف مسجلة في المتحف حالياً.</td></tr>';
        return;
      }

      tbody.innerHTML = items.map(item => `
        <tr class="hover:bg-slate-900/60 transition">
          <td class="p-2.5">
            <div class="flex items-center gap-2">
              <span class="text-xl">${item.icon || '🏺'}</span>
              <div>
                <strong class="text-white block font-bold text-xs">${item.name}</strong>
                <span class="text-[10px] text-slate-400">${item.edition || 'إصدار ملكي'}</span>
              </div>
            </div>
          </td>
          <td class="p-2.5">
            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${item.rarity === 'mythic' ? 'bg-amber-500/20 text-amber-300' : 'bg-purple-500/20 text-purple-300'}">
              ${item.rarityLabel || item.rarity}
            </span>
            <span class="text-[10px] text-slate-400 block mt-0.5">${item.category || 'آثار'}</span>
          </td>
          <td class="p-2.5 text-center font-bold text-xs ${item.stock > 0 ? 'text-amber-400' : 'text-rose-400'}">
            ${item.stock} قطعة
          </td>
          <td class="p-2.5 text-center font-bold font-mono text-emerald-400 text-xs">
            ${Number(item.buybackPrice || 0).toLocaleString()} EGP
          </td>
          <td class="p-2.5 text-left">
            <div class="flex items-center justify-end gap-1.5">
              <button onclick="window._adminLaunchAuctionForRelic('${item.id}')"
                class="px-2.5 py-1 rounded-lg bg-amber-500/20 hover:bg-amber-500/30 text-amber-300 text-[10px] font-bold border border-amber-500/40 transition cursor-pointer flex items-center gap-1">
                <i class="fa-solid fa-gavel"></i>
                <span>إطلاق مزاد 🔨</span>
              </button>
              <button onclick="window._adminDeleteMuseumRelic('${item.id}', '${(item.name || '').replace(/'/g, "\\'")}')"
                class="w-7 h-7 rounded-lg bg-rose-500/20 hover:bg-rose-500/30 text-rose-400 flex items-center justify-center text-xs transition cursor-pointer" title="حذف التحفة">
                <i class="fa-solid fa-trash-can"></i>
              </button>
            </div>
          </td>
        </tr>
      `).join('');
    } catch (e) {}
  };

  window._adminSubmitMintMuseumRelic = async function() {
    const name = (document.getElementById('adm-input-mus-name')?.value || '').trim();
    const category = (document.getElementById('adm-input-mus-category')?.value || 'آثار فرعونية ملكية').trim();
    const rarity = document.getElementById('adm-input-mus-rarity')?.value || 'epic';
    const icon = (document.getElementById('adm-input-mus-icon')?.value || '🏺').trim();
    const buybackPrice = Number(document.getElementById('adm-input-mus-buyback')?.value || 25000000);
    const stock = Number(document.getElementById('adm-input-mus-stock')?.value || 1);
    const edition = (document.getElementById('adm-input-mus-edition')?.value || 'نسخة فريدة 1/1').trim();
    const description = (document.getElementById('adm-input-mus-desc')?.value || '').trim();

    if (!name) {
      if (typeof showToast === 'function') showToast('خطأ', 'اسم التحفة الأثرية مطلوب.', 'warning');
      else alert('اسم التحفة الأثرية مطلوب.');
      return;
    }

    try {
      const res = await fetch(getAdminApiUrl('/api/museum/admin/mint'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${getAdminApiMasterKey()}`
        },
        body: JSON.stringify({ name, category, rarity, icon, buybackPrice, stock, edition, description })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'فشل سك التحفة.');

      if (typeof showToast === 'function') showToast('سك التحف الملكية 🏛️', `تم سك ونشر [${name}] في المتحف الملكي بنجاح!`, 'success');
      else alert(`تم سك ونشر [${name}] في المتحف الملكي بنجاح!`);

      if (typeof logAdminAction === 'function') logAdminAction(`سك تحفة جديدة بالمتحف: ${name}`);
      window._adminRefreshMuseumCatalog();
    } catch (e) {
      if (typeof showToast === 'function') showToast('خطأ', e.message, 'error');
      else alert(e.message);
    }
  };

  window._adminDeleteMuseumRelic = async function(id, name) {
    if (!confirm(`هل أنت متأكد من حذف [${name}] من المتحف؟`)) return;

    try {
      const res = await fetch(getAdminApiUrl('/api/museum/admin/delete'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${getAdminApiMasterKey()}`
        },
        body: JSON.stringify({ id })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'فشل حذف التحفة.');

      if (typeof showToast === 'function') showToast('حذف تحفة 🗑️', 'تم حذف التحفة من المتحف.', 'info');
      window._adminRefreshMuseumCatalog();
    } catch (e) {
      if (typeof showToast === 'function') showToast('خطأ', e.message, 'error');
      else alert(e.message);
    }
  };

  window._adminLaunchAuctionForRelic = async function(relicId) {
    try {
      const res = await fetch(getAdminApiUrl('/api/museum/items'));
      if (!res.ok) return;
      const data = await res.json();
      const item = (data.items || []).find(i => String(i.id) === String(relicId));
      if (!item) return;

      const nameEl = document.getElementById('adm-input-auc-name');
      const typeEl = document.getElementById('adm-input-auc-type');
      const iconEl = document.getElementById('adm-input-auc-icon');
      const badgeEl = document.getElementById('adm-input-auc-badge');
      const descEl = document.getElementById('adm-input-auc-desc');
      const startPriceEl = document.getElementById('adm-input-auc-start-price');
      const minStepEl = document.getElementById('adm-input-auc-min-step');
      const minNetWorthEl = document.getElementById('adm-input-auc-min-networth');

      if (nameEl) nameEl.value = item.name;
      if (typeEl) typeEl.value = 'museum_item';
      if (iconEl) iconEl.value = item.icon || '🏺';
      if (badgeEl) badgeEl.value = item.edition || 'تحفة متحف ملكية';
      if (descEl) descEl.value = item.description || 'تحفة أثرية نادرة مسجلة بالمتحف الملكي.';
      if (startPriceEl) startPriceEl.value = Math.max(10000000, Math.floor(Number(item.buybackPrice || 25000000) * 0.8));
      if (minStepEl) minStepEl.value = 1000000;
      if (minNetWorthEl) minNetWorthEl.value = Math.max(20000000, Math.floor(Number(item.buybackPrice || 25000000) * 0.5));

      // Scroll to auction form smoothly
      document.getElementById('adm-input-auc-name')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      if (typeof showToast === 'function') showToast('تجهيز المزاد 🔨', `تم تجهيز إعدادات المزاد للتحفة [${item.name}]! اضغط على نشر المزاد.`, 'info');
    } catch (e) {}
  };

  // Auto-load museum catalog when auctions tab is opened
  document.addEventListener('DOMContentLoaded', () => {
    const aucTab = document.getElementById('tab-admin-auctions');
    if (aucTab) {
      aucTab.addEventListener('click', () => {
        setTimeout(() => {
          if (typeof window._adminRefreshMuseumCatalog === 'function') {
            window._adminRefreshMuseumCatalog();
          }
        }, 150);
      });
    }
  });

;
